select public.upsert_bank_question($json${"id":"lei2-easy-001","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":2,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Em que dia descansou Deus de toda a sua obra?","bible_ref":"Génesis 2:2","verse_text":"E acabou Deus no dia sétimo sua obra que fez, e repousou o dia sétimo de toda sua obra que havia feito."},"fr":{"prompt":"Quel jour Dieu se reposa-t-il de toute son œuvre ?","bible_ref":"Genèse 2:2","verse_text":"Dieu acheva au septième jour son œuvre, qu’il avait faite: et il se reposa au septième jour de toute son œuvre, qu’il avait faite."},"en":{"prompt":"On which day did God rest from all his work?","bible_ref":"Genesis 2:2","verse_text":"And on the seventh day God ended his work which he had made; and he rested on the seventh day from all his work which he had made."},"es":{"prompt":"¿En qué día reposó Dios de toda su obra?","bible_ref":"Génesis 2:2","verse_text":"Y acabó Dios en el día séptimo su obra que hizo, y reposó el día séptimo de toda su obra que había hecho."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No sétimo dia"},"fr":{"text":"Le septième jour"},"en":{"text":"On the seventh day"},"es":{"text":"El día séptimo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No primeiro dia"},"fr":{"text":"Le premier jour"},"en":{"text":"On the first day"},"es":{"text":"El día primero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No terceiro dia"},"fr":{"text":"Le troisième jour"},"en":{"text":"On the third day"},"es":{"text":"El día tercero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No sexto dia"},"fr":{"text":"Le sixième jour"},"en":{"text":"On the sixth day"},"es":{"text":"El día sexto"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-002","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":3,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Que nome deu Adão à sua mulher?","bible_ref":"Génesis 3:20","verse_text":"E chamou o homem o nome de sua mulher, Eva; porquanto ela era mãe de todos o viventes."},"fr":{"prompt":"Quel nom Adam donna-t-il à sa femme ?","bible_ref":"Genèse 3:20","verse_text":"Adam donna à sa femme le nom d’Ève: car elle a été la mère de tous les vivants."},"en":{"prompt":"What name did Adam give his wife?","bible_ref":"Genesis 3:20","verse_text":"And Adam called his wife’s name Eve; because she was the mother of all living."},"es":{"prompt":"¿Qué nombre puso Adam a su mujer?","bible_ref":"Génesis 3:20","verse_text":"Y llamó el hombre el nombre de su mujer, Eva; por cuanto ella era madre de todos los vivientes."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Eva"},"fr":{"text":"Ève"},"en":{"text":"Eve"},"es":{"text":"Eva"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sara"},"fr":{"text":"Sara"},"en":{"text":"Sarah"},"es":{"text":"Sara"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Raquel"},"fr":{"text":"Rachel"},"en":{"text":"Rachel"},"es":{"text":"Rachêl"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rebeca"},"fr":{"text":"Rebecca"},"en":{"text":"Rebekah"},"es":{"text":"Rebeca"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-003","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":2,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Onde plantou o SENHOR Deus um jardim, do lado do oriente?","bible_ref":"Génesis 2:8","verse_text":"E havia o SENHOR Deus plantado um jardim em Éden ao oriente, e pôs ali ao homem que havia formado."},"fr":{"prompt":"Où l’Éternel Dieu planta-t-il un jardin, du côté de l’orient ?","bible_ref":"Genèse 2:8","verse_text":"Puis l’Éternel Dieu planta un jardin en Éden, du côté de l’orient, et il y mit l’homme qu’il avait formé."},"en":{"prompt":"Where did the LORD God plant a garden, eastward?","bible_ref":"Genesis 2:8","verse_text":"And the LORD God planted a garden eastward in Eden; and there he put the man whom he had formed."},"es":{"prompt":"¿Dónde plantó Jehová Dios un huerto, al oriente?","bible_ref":"Génesis 2:8","verse_text":"Y había Jehová Dios plantado un huerto en Edén al oriente, y puso allí al hombre que había formado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em Éden"},"fr":{"text":"En Éden"},"en":{"text":"In Eden"},"es":{"text":"En Edén"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em Babel"},"fr":{"text":"À Babel"},"en":{"text":"In Babel"},"es":{"text":"En Babel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No Egito"},"fr":{"text":"En Égypte"},"en":{"text":"In Egypt"},"es":{"text":"En Egipto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Em Sodoma"},"fr":{"text":"À Sodome"},"en":{"text":"In Sodom"},"es":{"text":"En Sodoma"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-004","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":2,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Quem viu a cesta do bebé Moisés entre os juncos, junto ao rio?","bible_ref":"Êxodo 2:5","verse_text":"E a filha de Faraó desceu a lavar-se ao rio, e passeando suas virgens pela beira do rio, viu ela a cesta entre os juncos, e enviou uma criada sua a que a tomasse."},"fr":{"prompt":"Qui aperçut la caisse du petit Moïse au milieu des roseaux, près du fleuve ?","bible_ref":"Exode 2:5","verse_text":"La fille de Pharaon descendit au fleuve pour se baigner, et ses compagnes se promenèrent le long du fleuve. Elle aperçut la caisse au milieu des roseaux, et elle envoya sa servante pour la prendre."},"en":{"prompt":"Who saw baby Moses’ ark among the flags by the river?","bible_ref":"Exodus 2:5","verse_text":"And the daughter of Pharaoh came down to wash herself at the river; and her maidens walked along by the river’s side; and when she saw the ark among the flags, she sent her maid to fetch it."},"es":{"prompt":"¿Quién vio la arquilla del niño Moisés en el carrizal, junto al río?","bible_ref":"Éxodo 2:5","verse_text":"Y la hija de Faraón descendió á lavarse al río, y paseándose sus doncellas por la ribera del río, vió ella la arquilla en el carrizal, y envió una criada suya á que la tomase."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A filha do Faraó"},"fr":{"text":"La fille de Pharaon"},"en":{"text":"Pharaoh’s daughter"},"es":{"text":"La hija de Faraón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A mulher do Faraó"},"fr":{"text":"La femme de Pharaon"},"en":{"text":"Pharaoh’s wife"},"es":{"text":"La mujer de Faraón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um pastor"},"fr":{"text":"Un berger"},"en":{"text":"A shepherd"},"es":{"text":"Un pastor"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um soldado egípcio"},"fr":{