select public.upsert_bank_question($json${"id":"lei2-easy-005","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":4,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Segundo Êxodo 4:14, como se chamava o irmão de Moisés?","bible_ref":"Êxodo 4:14","verse_text":"Então o SENHOR se irou contra Moisés, e disse: Não conheço eu a teu irmão Arão, levita, e que ele fala bem? E ainda eis que ele sairá para te receber, e vendo-te, se alegrará em seu coração."},"fr":{"prompt":"D’après Exode 4:14, comment s’appelait le frère de Moïse ?","bible_ref":"Exode 4:14","verse_text":"Alors la colère de l’Éternel s’enflamma contre Moïse, et il dit: N’y a t-il pas ton frère Aaron, le Lévite? Je sais qu’il parlera facilement. Le voici lui-même, qui vient au-devant de toi; et, quand il te verra, il se réjouira dans son cœur."},"en":{"prompt":"According to Exodus 4:14, what was the name of Moses’ brother?","bible_ref":"Exodus 4:14","verse_text":"And the anger of the LORD was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart."},"es":{"prompt":"Según Éxodo 4:14, ¿cómo se llamaba el hermano de Moisés?","bible_ref":"Éxodo 4:14","verse_text":"Entonces Jehová se enojó contra Moisés, y dijo: ¿No conozco yo á tu hermano Aarón, Levita, y que él hablará? Y aun he aquí que él te saldrá á recibir, y en viéndote, se alegrará en su corazón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jetro"},"fr":{"text":"Jéthro"},"en":{"text":"Jethro"},"es":{"text":"Jethro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-006","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":13,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"De noite, como ia o SENHOR diante do povo para o iluminar?","bible_ref":"Êxodo 13:21","verse_text":"E o SENHOR ia diante deles de dia em uma coluna de nuvem, para guiá-los pelo caminho; e de noite em uma coluna de fogo para iluminá-los, a fim de que andassem de dia e de noite."},"fr":{"prompt":"La nuit, comment l’Éternel allait-il devant le peuple pour l’éclairer ?","bible_ref":"Exode 13:21","verse_text":"L’Éternel allait devant eux, le jour dans une colonne de nuée pour les guider dans leur chemin, et la nuit dans une colonne de feu pour les éclairer, afin qu’ils marchassent jour et nuit."},"en":{"prompt":"By night, how did the LORD go before the people to give them light?","bible_ref":"Exodus 13:21","verse_text":"And the LORD went before them by day in a pillar of a cloud, to lead them the way; and by night in a pillar of fire, to give them light; to go by day and night:"},"es":{"prompt":"De noche, ¿cómo iba Jehová delante del pueblo para alumbrarle?","bible_ref":"Éxodo 13:21","verse_text":"Y Jehová iba delante de ellos de día en una columna de nube, para guiarlos por el camino; y de noche en una columna de fuego para alumbrarles; á fin de que anduviesen de día y de noche."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Numa coluna de fogo"},"fr":{"text":"Dans une colonne de feu"},"en":{"text":"In a pillar of fire"},"es":{"text":"En una columna de fuego"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Numa estrela brilhante"},"fr":{"text":"Dans une étoile brillante"},"en":{"text":"In a bright star"},"es":{"text":"En una estrella brillante"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Num anjo com uma tocha"},"fr":{"text":"Dans un ange portant une torche"},"en":{"text":"In an angel with a torch"},"es":{"text":"En un ángel con una antorcha"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Na lua cheia"},"fr":{"text":"Dans la pleine lune"},"en":{"text":"In the full moon"},"es":{"text":"En la luna llena"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-007","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":34,"verse_start":28,"verse_end":28,"texts":{"pt":{"prompt":"Segundo Êxodo 34:28, quantas palavras da aliança foram escritas nas tábuas?","bible_ref":"Êxodo 34:28","verse_text":"E ele esteve ali com o SENHOR quarenta dias e quarenta noites: não comeu pão, nem bebeu água; e escreveu em tábuas as palavras da aliança, os dez dizeres."},"fr":{"prompt":"D’après Exode 34:28, combien de paroles de l’alliance furent écrites sur les tables ?","bible_ref":"Exode 34:28","verse_text":"Moïse fut là avec l’Éternel quarante jours et quarante nuits. Il ne mangea point de pain, et il ne but point d’eau. Et l’Éternel écrivit sur les tables les paroles de l’alliance, les dix paroles."},"en":{"prompt":"According to Exodus 34:28, how many commandments of the covenant were written on the tables?","bible_ref":"Exodus 34:28","verse_text":"And he was there with the LORD forty days and forty nights; he did neither eat bread, nor drink water. And he wrote upon the tables the words of the covenant, the ten commandments."},"es":{"prompt":"Según Éxodo 34:28, ¿cuántas palabras de la alianza se escribieron en las tablas?","bible_ref":"Éxodo 34:28","verse_text":"Y él estuvo allí con Jehová cuarenta días y cuarenta noches: no comió pan, ni bebió agua; y escribió en tablas las palabras de la alianza, las diez palabras."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"10"},"fr":{"text":"10"},"en":{"text":"10"},"es":{"text":"10"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"12"},"fr":{"text":"12"},"en":{"text":"12"},"es":{"text":"12"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-008","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":3,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"O que mandou Deus Moisés tirar dos pés, por estar em terra santa?","bible_ref":"Êxodo 3:5","verse_text":"E disse: Não te aproximes daqui; tira teus calçados de teus pés, porque o lugar em que estás é terra santa."},"fr":{"prompt":"Qu’est-ce que Dieu ordonna à Moïse d’ôter de ses pieds, parce qu’il était sur une terre sainte ?","bible_ref":"Exode 3:5","verse_text":"Dieu dit: N’approche pas d’ici, ôte tes souliers de tes pieds, car le lieu sur lequel tu te tiens est une terre sainte."},"en":{"prompt":"What did God tell Moses to put off from his feet, because he stood on holy ground?","bible_ref":"Exodus 3:5","verse_text":"And he said, Draw not nigh hither: put off thy shoes from off thy feet, for the place whereon thou standest is holy ground."},"es":{"prompt":"¿Qué mandó Dios a Moisés quitarse de los pies, porque estaba en tierra santa?","bible_ref":"Éxodo 3:5","verse_text":"Y dijo: No te llegues acá: quita tus zapatos de tus pies, porque el lugar en que tú estás, tierra santa es."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os calçados"},"fr":{"text":"Ses souliers"},"en":{"text":"His shoes"},"es":{"text":"Sus zapatos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O pó"},"fr":{"text":"La poussière"},"en":{"text":"The dust"},"es":{"text":"El polvo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As correntes"},"fr":{"text":"Les chaînes"},"en":{"text":"The chains"},"es":{"text":"Las cadenas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os anéis"},"fr":{"text":"Les anneaux"},"en":{"text":"The rings"},"es":{"text":"Los anillos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-009","type":"choice","level":"easy","testament":"ot","book":"LEV","chapter":11,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Que animal tem as unhas fendidas mas não rumina, e por isso era impuro?","bible_ref":"Levítico 11:7","verse_text":"Também o porco, porque tem unhas, e é de unhas fendidas, mas não rumina, o tereis por impuro."},"fr":{"prompt":"Quel animal a le pied fourchu mais ne rumine pas, et était donc impur ?","bible_ref":"Lévitique 11:7","verse_text":"Vous ne mangerez pas le porc, qui a la corne fendue et le pied fourchu, mais qui ne rumine pas: vous le regarderez comme impur."},"en":{"prompt":"Which animal divides the hoof but does not chew the cud, and so was unclean?","bible_ref":"Leviticus 11:7","verse_text":"And the swine, though he divide the hoof, and be clovenfooted, yet he cheweth not the cud; he is unclean to you."},"es":{"prompt":"¿Qué animal tiene pezuñas hendidas pero no rumia, y por eso era inmundo?","bible_ref":"Levítico 11:7","verse_text":"También el puerco, porque tiene pezuñas, y es de pezuñas hendidas, mas no rumia, tendréislo por inmundo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O porco"},"fr":{"text":"Le porc"},"en":{"text":"The swine"},"es":{"text":"El puerco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A ovelha"},"fr":{"text":"La brebis"},"en":{"text":"The sheep"},"es":{"text":"La oveja"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O boi"},"fr":{"text":"Le bœuf"},"en":{"text":"The ox"},"es":{"text":"El buey"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A cabra"},"fr":{"text":"La chèvre"},"en":{"text":"The goat"},"es":{"text":"La cabra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-010","type":"choice","level":"easy","testament":"ot","book":"LEV","chapter":11,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Que animais das águas podiam os israelitas comer?","bible_ref":"Levítico 11:9","verse_text":"Isto comereis de todas as coisas que estão nas águas: todas as coisas que têm barbatanas e escamas nas águas do mar, e nos rios, aquelas comereis;"},"fr":{"prompt":"Quels animaux des eaux les Israélites pouvaient-ils manger ?","bible_ref":"Lévitique 11:9","verse_text":"Voici les animaux dont vous mangerez parmi tous ceux qui sont dans les eaux. Vous mangerez de tous ceux qui ont des nageoires et des écailles, et qui sont dans les eaux, soit dans les mers, soit dans les rivières."},"en":{"prompt":"Which creatures of the waters could the Israelites eat?","bible_ref":"Leviticus 11:9","verse_text":"These shall ye eat of all that are in the waters: whatsoever hath fins and scales in the waters, in the seas, and in the rivers, them shall ye eat."},"es":{"prompt":"¿Qué animales de las aguas podían comer los israelitas?","bible_ref":"Levítico 11:9","verse_text":"Esto comeréis de todas las cosas que están en las aguas: todas las cosas que tienen aletas y escamas en las aguas de la mar, y en los ríos, aquellas comeréis;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os que têm barbatanas e escamas"},"fr":{"text":"Ceux qui ont des nageoires et des écailles"},"en":{"text":"Those that have fins and scales"},"es":{"text":"Los que tienen aletas y escamas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Todos os que nadam"},"fr":{"text":"Tous ceux qui nagent"},"en":{"text":"All that swim"},"es":{"text":"Todos los que nadan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Só os que não têm escamas"},"fr":{"text":"Seulement ceux qui n’ont pas d’écailles"},"en":{"text":"Only those without scales"},"es":{"text":"Solo los que no tienen escamas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nenhum animal das águas"},"fr":{"text":"Aucun animal des eaux"},"en":{"text":"No creature of the waters"},"es":{"text":"Ningún animal de las aguas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-011","type":"choice","level":"easy","testament":"ot","book":"NUM","chapter":14,"verse_start":33,"verse_end":33,"texts":{"pt":{"prompt":"Quantos anos andariam os filhos de Israel pelo deserto?","bible_ref":"Números 14:33","verse_text":"E vossos filhos andarão pastoreando no deserto quarenta anos, e eles levarão vossas prostituições, até que vossos corpos sejam consumidos no deserto."},"fr":{"prompt":"Combien d’années les enfants d’Israël resteraient-ils dans le désert ?","bible_ref":"Nombres 14:33","verse_text":"et vos enfants paîtront quarante années dans le désert, et porteront la peine de vos infidélités, jusqu’à ce que vos cadavres soient tous tombés dans le désert."},"en":{"prompt":"How many years would the children of Israel wander in the wilderness?","bible_ref":"Numbers 14:33","verse_text":"And your children shall wander in the wilderness forty years, and bear your whoredoms, until your carcases be wasted in the wilderness."},"es":{"prompt":"¿Cuántos años andarían los hijos de Israel por el desierto?","bible_ref":"Números 14:33","verse_text":"Y vuestros hijos andarán pastoreando en el desierto cuarenta años, y ellos llevarán vuestras fornicaciones, hasta que vuestros cuerpos sean consumidos en el desierto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"40"},"fr":{"text":"40"},"en":{"text":"40"},"es":{"text":"40"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"12"},"fr":{"text":"12"},"en":{"text":"12"},"es":{"text":"12"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"100"},"fr":{"text":"100"},"en":{"text":"100"},"es":{"text":"100"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-012","type":"choice","level":"easy","testament":"ot","book":"NUM","chapter":13,"verse_start":23,"verse_end":24,"texts":{"pt":{"prompt":"Que trouxeram os espias de Escol, levado por dois homens numa vara?","bible_ref":"Números 13:23-24","verse_text":"E chegaram até o ribeiro de Escol, e dali cortaram um ramo com um cacho de uvas, o qual trouxeram dois em uma vara, e das romãs e dos figos. E chamou-se aquele lugar vale de Escol pelo cacho que cortaram dali os filhos de Israel."},"fr":{"prompt":"Que rapportèrent les espions d’Eschcol, porté à deux sur une perche ?","bible_ref":"Nombres 13:23-24","verse_text":"Ils arrivèrent jusqu’à la vallée d’Eschcol, où ils coupèrent une branche de vigne avec une grappe de raisin, qu’ils portèrent à deux au moyen d’une perche; ils prirent aussi des grenades et des figues. On donna à ce lieu le nom de vallée d’Eschcol, à cause de la grappe que les enfants d’Israël y coupèrent."},"en":{"prompt":"What did the spies bring from Eshcol, carried by two men on a staff?","bible_ref":"Numbers 13:23-24","verse_text":"And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and they brought of the pomegranates, and of the figs. The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence."},"es":{"prompt":"¿Qué trajeron los espías de Escol, llevado por dos en un palo?","bible_ref":"Números 13:23-24","verse_text":"Y subieron por el mediodía, y vinieron hasta Hebrón: y allí estaban Aimán, y Sesai, y Talmai, hijos de Anac. Hebrón fué edificada siete años antes de Zoán, la de Egipto. Y llegaron hasta el arroyo de Escol, y de allí cortaron un sarmiento con un racimo de uvas, el cual trajeron dos en un palo, y de las granadas y de los higos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um cacho de uvas"},"fr":{"text":"Une grappe de raisin"},"en":{"text":"A cluster of grapes"},"es":{"text":"Un racimo de uvas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um saco de trigo"},"fr":{"text":"Un sac de blé"},"en":{"text":"A sack of corn"},"es":{"text":"Un saco de trigo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um cesto de maçãs"},"fr":{"text":"Un panier de pommes"},"en":{"text":"A basket of apples"},"es":{"text":"Un cesto de manzanas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um jarro de mel"},"fr":{"text":"Une jarre de miel"},"en":{"text":"A jar of honey"},"es":{"text":"Un cántaro de miel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-013","type":"choice","level":"easy","testament":"ot","book":"NUM","chapter":12,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Em Números 12:10, quem ficou leprosa como a neve?","bible_ref":"Números 12:10","verse_text":"E a nuvem se afastou da tenda; e eis que Miriã era leprosa como a neve; e Arão olhou para Miriã, e eis que estava leprosa."},"fr":{"prompt":"En Nombres 12:10, qui fut frappée d’une lèpre blanche comme la neige ?","bible_ref":"Nombres 12:10","verse_text":"La nuée se retira de dessus la tente. Et voici, Marie était frappée d’une lèpre, blanche comme la neige. Aaron se tourna vers Marie; et voici, elle avait la lèpre."},"en":{"prompt":"In Numbers 12:10, who became leprous, white as snow?","bible_ref":"Numbers 12:10","verse_text":"And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."},"es":{"prompt":"En Números 12:10, ¿quién quedó leprosa como la nieve?","bible_ref":"Números 12:10","verse_text":"Y la nube se apartó del tabernáculo: y he aquí que María era leprosa como la nieve; y miró Aarón á María, y he aquí que estaba leprosa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Miriã"},"fr":{"text":"Marie"},"en":{"text":"Miriam"},"es":{"text":"María"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zípora"},"fr":{"text":"Séphora"},"en":{"text":"Zipporah"},"es":{"text":"Séphora"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Joquebede"},"fr":{"text":"Jokébed"},"en":{"text":"Jochebed"},"es":{"text":"Jochêbed"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sara"},"fr":{"text":"Sara"},"en":{"text":"Sarah"},"es":{"text":"Sara"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-014","type":"choice","level":"easy","testament":"ot","book":"DEU","chapter":34,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Quem ficou cheio do espírito de sabedoria, porque Moisés tinha posto as mãos sobre ele?","bible_ref":"Deuteronómio 34:9","verse_text":"E Josué filho de Num foi cheio de espírito de sabedoria, porque Moisés havia posto suas mãos sobre ele: e os filhos de Israel lhe obedeceram, e fizeram como o SENHOR mandou a Moisés."},"fr":{"prompt":"Qui fut rempli de l’esprit de sagesse, parce que Moïse avait posé ses mains sur lui ?","bible_ref":"Deutéronome 34:9","verse_text":"Josué, fils de Nun, était rempli de l’esprit de sagesse, car Moïse avait posé ses mains sur lui. Les enfants d’Israël lui obéirent, et se conformèrent aux ordres que l’Éternel avait donnés à Moïse."},"en":{"prompt":"Who was full of the spirit of wisdom, because Moses had laid his hands upon him?","bible_ref":"Deuteronomy 34:9","verse_text":"And Joshua the son of Nun was full of the spirit of wisdom; for Moses had laid his hands upon him: and the children of Israel hearkened unto him, and did as the LORD commanded Moses."},"es":{"prompt":"¿Quién fue lleno de espíritu de sabiduría, porque Moisés había puesto sus manos sobre él?","bible_ref":"Deuteronomio 34:9","verse_text":"Y Josué hijo de Nun fué lleno de espíritu de sabiduría, porque Moisés había puesto sus manos sobre él: y los hijos de Israel le obedecieron, é hicieron como Jehová mandó á Moisés."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Eleazar"},"fr":{"text":"Éléazar"},"en":{"text":"Eleazar"},"es":{"text":"Eleazar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-015","type":"choice","level":"easy","testament":"ot","book":"DEU","chapter":6,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"A quem devias repetir as palavras de Deus, em casa e pelo caminho?","bible_ref":"Deuteronómio 6:7","verse_text":"E as repetirás a teus filhos, e falarás delas estando em tua casa, e andando pelo caminho, e ao deitar-te, e quando te levantes:"},"fr":{"prompt":"À qui fallait-il inculquer les paroles de Dieu, à la maison et en voyage ?","bible_ref":"Deutéronome 6:7","verse_text":"Tu les inculqueras à tes enfants, et tu en parleras quand tu seras dans ta maison, quand tu iras en voyage, quand tu te coucheras et quand tu te lèveras."},"en":{"prompt":"To whom were God’s words to be taught, at home and by the way?","bible_ref":"Deuteronomy 6:7","verse_text":"And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up."},"es":{"prompt":"¿A quién había que repetir las palabras de Dios, en casa y por el camino?","bible_ref":"Deuteronomio 6:7","verse_text":"Y las repetirás á tus hijos, y hablarás de ellas estando en tu casa, y andando por el camino, y al acostarte, y cuando te levantes:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Aos teus filhos"},"fr":{"text":"À tes enfants"},"en":{"text":"To thy children"},"es":{"text":"A tus hijos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Aos reis"},"fr":{"text":"Aux rois"},"en":{"text":"To the kings"},"es":{"text":"A los reyes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Aos estrangeiros"},"fr":{"text":"Aux étrangers"},"en":{"text":"To the strangers"},"es":{"text":"A los extranjeros"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Aos animais"},"fr":{"text":"Aux animaux"},"en":{"text":"To the animals"},"es":{"text":"A los animales"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-016","type":"choice","level":"easy","testament":"ot","book":"DEU","chapter":5,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Em quantas tábuas de pedra escreveu o SENHOR as suas palavras?","bible_ref":"Deuteronómio 5:22","verse_text":"Estas palavras falou o SENHOR a toda vossa congregação no monte, do meio do fogo, da nuvem e da escuridão, a grande voz: e não acrescentou mais. E escreveu-os em duas tábuas de pedra, as quais deu a mim."},"fr":{"prompt":"Sur combien de tables de pierre l’Éternel écrivit-il ses paroles ?","bible_ref":"Deutéronome 5:22","verse_text":"Telles sont les paroles que prononça l’Éternel à haute voix sur la montagne, du milieu du feu, des nuées et de l’obscurité, et qu’il adressa à toute votre assemblée, sans rien ajouter. Il les écrivit sur deux tables de pierre, qu’il me donna."},"en":{"prompt":"On how many tables of stone did the LORD write his words?","bible_ref":"Deuteronomy 5:22","verse_text":"These words the LORD spake unto all your assembly in the mount out of the midst of the fire, of the cloud, and of the thick darkness, with a great voice: and he added no more. And he wrote them in two tables of stone, and delivered them unto me."},"es":{"prompt":"¿En cuántas tablas de piedra escribió Jehová sus palabras?","bible_ref":"Deuteronomio 5:22","verse_text":"Estas palabras habló Jehová á toda vuestra congregación en el monte, de en medio del fuego, de la nube y de la oscuridad, á gran voz: y no añadió más. Y escribiólas en dos tablas de piedra, las cuales me dió á mí."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"2"},"fr":{"text":"2"},"en":{"text":"2"},"es":{"text":"2"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"1"},"fr":{"text":"1"},"en":{"text":"1"},"es":{"text":"1"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}},{"position":4,"is_correct":false,"texts":{"pt":{"tex