select public.upsert_bank_question($json${"id":"lei2-easy-017","type":"choice","level":"easy","testament":"ot","book":"DEU","chapter":8,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Durante a viagem pelo deserto, o que nunca envelheceu sobre o povo?","bible_ref":"Deuteronómio 8:4","verse_text":"Tua roupa nunca se envelheceu sobre ti, nem o pé se te inchou por estes quarenta anos."},"fr":{"prompt":"Pendant la marche dans le désert, qu’est-ce qui ne s’est point usé sur le peuple ?","bible_ref":"Deutéronome 8:4","verse_text":"Ton vêtement ne s’est point usé sur toi, et ton pied ne s’est point enflé, pendant ces quarante années."},"en":{"prompt":"During the journey in the wilderness, what never waxed old upon the people?","bible_ref":"Deuteronomy 8:4","verse_text":"Thy raiment waxed not old upon thee, neither did thy foot swell, these forty years."},"es":{"prompt":"Durante el viaje por el desierto, ¿qué nunca se envejeció sobre el pueblo?","bible_ref":"Deuteronomio 8:4","verse_text":"Tu vestido nunca se envejeció sobre ti, ni el pie se te ha hinchado por estos cuarenta años."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A roupa"},"fr":{"text":"Le vêtement"},"en":{"text":"Their raiment"},"es":{"text":"El vestido"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"As tendas"},"fr":{"text":"Les tentes"},"en":{"text":"Their tents"},"es":{"text":"Las tiendas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O cabelo"},"fr":{"text":"Les cheveux"},"en":{"text":"Their hair"},"es":{"text":"El cabello"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"As armas"},"fr":{"text":"Les armes"},"en":{"text":"Their weapons"},"es":{"text":"Las armas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-easy-018","type":"choice","level":"easy","testament":"ot","book":"DEU","chapter":6,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Onde devia o povo escrever as palavras de Deus?","bible_ref":"Deuteronómio 6:9","verse_text":"E as escreverás nos umbrais de tua casa, e em tuas entradas."},"fr":{"prompt":"Où le peuple devait-il écrire les paroles de Dieu ?","bible_ref":"Deutéronome 6:9","verse_text":"Tu les écriras sur les poteaux de ta maison et sur tes portes."},"en":{"prompt":"Where were the people to write God’s words?","bible_ref":"Deuteronomy 6:9","verse_text":"And thou shalt write them upon the posts of thy house, and on thy gates."},"es":{"prompt":"¿Dónde debía el pueblo escribir las palabras de Dios?","bible_ref":"Deuteronomio 6:9","verse_text":"Y las escribirás en los postes de tu casa, y en tus portadas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nos umbrais da casa e nas entradas"},"fr":{"text":"Sur les poteaux de la maison et sur les portes"},"en":{"text":"On the posts of the house and on the gates"},"es":{"text":"En los postes de la casa y en las portadas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nas paredes do templo"},"fr":{"text":"Sur les murs du temple"},"en":{"text":"On the walls of the temple"},"es":{"text":"En las paredes del templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Na areia do deserto"},"fr":{"text":"Sur le sable du désert"},"en":{"text":"In the sand of the desert"},"es":{"text":"En la arena del desierto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nas vestes dos sacerdotes"},"fr":{"text":"Sur les vêtements des sacrificateurs"},"en":{"text":"On the priests’ garments"},"es":{"text":"En las vestiduras de los sacerdotes"}}}]}$json$::jsonb);
