select public.upsert_bank_question($json${"id":"lei2-medium-003","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":39,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Quem comprou José aos ismaelitas, quando ele foi levado ao Egito?","bible_ref":"Génesis 39:1","verse_text":"E levado José ao Egito, comprou-o Potifar, oficial de Faraó, capitão dos da guarda, homem egípcio, da mão dos ismaelitas que o haviam levado ali."},"fr":{"prompt":"Qui acheta Joseph aux Ismaélites, quand il fut descendu en Égypte ?","bible_ref":"Genèse 39:1","verse_text":"On fit descendre Joseph en Égypte; et Potiphar, officier de Pharaon, chef des gardes, Égyptien, l’acheta des Ismaélites qui l’y avaient fait descendre."},"en":{"prompt":"Who bought Joseph of the Ishmeelites when he was brought down to Egypt?","bible_ref":"Genesis 39:1","verse_text":"And Joseph was brought down to Egypt; and Potiphar, an officer of Pharaoh, captain of the guard, an Egyptian, bought him of the hands of the Ishmeelites, which had brought him down thither."},"es":{"prompt":"¿Quién compró a José de mano de los Ismaelitas, cuando fue llevado a Egipto?","bible_ref":"Génesis 39:1","verse_text":"Y llevado José á Egipto, comprólo Potiphar, eunuco de Faraón, capitán de los de la guardia, varón Egipcio, de mano de los Ismaelitas que lo habían llevado allá."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Potifar"},"fr":{"text":"Potiphar"},"en":{"text":"Potiphar"},"es":{"text":"Potiphar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Labão"},"fr":{"text":"Laban"},"en":{"text":"Laban"},"es":{"text":"Labán"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abimeleque"},"fr":{"text":"Abimélec"},"en":{"text":"Abimelech"},"es":{"text":"Abimelech"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ló"},"fr":{"text":"Lot"},"en":{"text":"Lot"},"es":{"text":"Lot"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-004","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":15,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Que profetisa, irmã de Arão, tomou um pandeiro na mão e saiu com as mulheres?","bible_ref":"Êxodo 15:20","verse_text":"E Miriã a profetisa, irmã de Arão, tomou um pandeiro em sua mão, e todas as mulheres saíram atrás dela com pandeiros e danças."},"fr":{"prompt":"Quelle prophétesse, sœur d’Aaron, prit un tambourin et sortit avec les femmes ?","bible_ref":"Exode 15:20","verse_text":"Marie, la prophétesse, sœur d’Aaron, prit à sa main un tambourin, et toutes les femmes vinrent après elle, avec des tambourins et en dansant."},"en":{"prompt":"Which prophetess, the sister of Aaron, took a timbrel in her hand and went out with the women?","bible_ref":"Exodus 15:20","verse_text":"And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."},"es":{"prompt":"¿Qué profetisa, hermana de Aarón, tomó un pandero y salió con las mujeres?","bible_ref":"Éxodo 15:20","verse_text":"Y María la profetisa, hermana de Aarón, tomó un pandero en su mano, y todas las mujeres salieron en pos de ella con panderos y danzas;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Miriã"},"fr":{"text":"Marie"},"en":{"text":"Miriam"},"es":{"text":"María"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zípora"},"fr":{"text":"Séphora"},"en":{"text":"Zipporah"},"es":{"text":"Séphora"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Joquebede"},"fr":{"text":"Jokébed"},"en":{"text":"Jochebed"},"es":{"text":"Jochêbed"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Agar"},"fr":{"text":"Agar"},"en":{"text":"Hagar"},"es":{"text":"Agar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-005","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":15,"verse_start":25,"verse_end":25,"texts":{"pt":{"prompt":"O que mostrou o SENHOR a Moisés para tornar as águas doces?","bible_ref":"Êxodo 15:25","verse_text":"E Moisés clamou ao SENHOR; e o SENHOR lhe mostrou uma árvore, a qual quando a meteu dentro das águas, as águas se tornaram doces. Ali lhes deu estatutos e ordenanças, e ali os provou;"},"fr":{"prompt":"Que montra l’Éternel à Moïse pour rendre l’eau douce ?","bible_ref":"Exode 15:25","verse_text":"Moïse cria à l’Éternel; et l’Éternel lui indiqua un bois, qu’il jeta dans l’eau. Et l’eau devint douce. Ce fut là que l’Éternel donna au peuple des lois et des ordonnances, et ce fut là qu’il le mit à l’épreuve."},"en":{"prompt":"What did the LORD shew Moses to make the waters sweet?","bible_ref":"Exodus 15:25","verse_text":"And he cried unto the LORD; and the LORD shewed him a tree, which when he had cast into the waters, the waters were made sweet: there he made for them a statute and an ordinance, and there he proved them,"},"es":{"prompt":"¿Qué mostró Jehová a Moisés para endulzar las aguas?","bible_ref":"Éxodo 15:25","verse_text":"Y Moisés clamó á Jehová; y Jehová le mostró un árbol, el cual metídolo que hubo dentro de las aguas, las aguas se endulzaron. Allí les dió estatutos y ordenanzas, y allí los probó;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma árvore"},"fr":{"text":"Un bois"},"en":{"text":"A tree"},"es":{"text":"Un árbol"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma pedra"},"fr":{"text":"Une pierre"},"en":{"text":"A stone"},"es":{"text":"Una piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um pouco de sal"},"fr":{"text":"Un peu de sel"},"en":{"text":"Some salt"},"es":{"text":"Un poco de sal"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um pedaço de pão"},"fr":{"text":"Un morceau de pain"},"en":{"text":"A piece of bread"},"es":{"text":"Un pedazo de pan"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-006","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":3,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Segundo Êxodo 3:14, o que respondeu Deus a Moisés sobre o seu nome?","bible_ref":"Êxodo 3:14","verse_text":"Deus respondeu a Moisés: EU SOU O QUE SOU. E disse: Assim dirás aos filhos de Israel: EU SOU me enviou a vós."},"fr":{"prompt":"D’après Exode 3:14, que répondit Dieu à Moïse au sujet de son nom ?","bible_ref":"Exode 3:14","verse_text":"Dieu dit à Moïse: Je suis celui qui suis. Et il ajouta: C’est ainsi que tu répondras aux enfants d’Israël: Celui qui s’appelle “je suis” m’a envoyé vers vous."},"en":{"prompt":"According to Exodus 3:14, what did God say to Moses about his name?","bible_ref":"Exodus 3:14","verse_text":"And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you."},"es":{"prompt":"Según Éxodo 3:14, ¿qué respondió Dios a Moisés sobre su nombre?","bible_ref":"Éxodo 3:14","verse_text":"Y respondió Dios á Moisés: YO SOY EL QUE SOY. Y dijo: Así dirás á los hijos de Israel: YO SOY me ha enviado á vosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"EU SOU O QUE SOU"},"fr":{"text":"Je suis celui qui suis"},"en":{"text":"I AM THAT I AM"},"es":{"text":"YO SOY EL QUE SOY"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O Deus dos exércitos"},"fr":{"text":"Le Dieu des armées"},"en":{"text":"The God of hosts"},"es":{"text":"El Dios de los ejércitos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O Rei dos reis"},"fr":{"text":"Le Roi des rois"},"en":{"text":"The King of kings"},"es":{"text":"El Rey de reyes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O Santo de Israel"},"fr":{"text":"Le Saint d’Israël"},"en":{"text":"The Holy One of Israel"},"es":{"text":"El Santo de Israel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-007","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":18,"verse_start":17,"verse_end":18,"texts":{"pt":{"prompt":"Quem disse a Moisés «Não fazes bem», porque ele não podia fazer tudo sozinho?","bible_ref":"Êxodo 18:17-18","verse_text":"Então o sogro de Moisés lhe disse: Não fazes bem: Desfalecerás de todo, tu, e também este povo que está contigo; porque o negócio é demasiado pesado para ti; não poderás fazê-lo tu sozinho."},"fr":{"prompt":"Qui dit à Moïse « Ce que tu fais n’est pas bien », car il ne pouvait pas y suffire seul ?","bible_ref":"Exode 18:17-18","verse_text":"Le beau-père de Moïse lui dit: Ce que tu fais n’est pas bien. Tu t’épuiseras toi-même, et tu épuiseras ce peuple qui est avec toi; car la chose est au-dessus de tes forces, tu ne pourras pas y suffire seul."},"en":{"prompt":"Who told Moses “The thing that thou doest is not good”, because he could not do it alone?","bible_ref":"Exodus 18:17-18","verse_text":"And Moses’ father in law said unto him, The thing that thou doest is not good. Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone."},"es":{"prompt":"¿Quién dijo a Moisés «No haces bien», porque no podía hacerlo solo?","bible_ref":"Éxodo 18:17-18","verse_text":"Entonces el suegro de Moisés le dijo: No haces bien: Desfallecerás del todo, tú, y también este pueblo que está contigo; porque el negocio es demasiado pesado para ti; no podrás hacerlo tú solo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O seu sogro"},"fr":{"text":"Son beau-père"},"en":{"text":"His father in law"},"es":{"text":"Su suegro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu irmão Arão"},"fr":{"text":"Son frère Aaron"},"en":{"text":"His brother Aaron"},"es":{"text":"Su hermano Aarón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josué"},