select public.upsert_bank_question($json${"id":"lei2-medium-008","type":"choice","level":"medium","testament":"ot","book":"LEV","chapter":25,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"No sétimo ano, o que não deviam fazer à terra e à vinha?","bible_ref":"Levítico 25:4","verse_text":"Mas no sétimo ano a terra terá um sábado de descanso, sábado ao SENHOR; não semearás a tua terra, nem podarás a tua vinha."},"fr":{"prompt":"La septième année, que ne fallait-il pas faire au champ et à la vigne ?","bible_ref":"Lévitique 25:4","verse_text":"Mais la septième année sera un sabbat, un temps de repos pour la terre, un sabbat en l’honneur de l’Éternel: tu n’ensemenceras point ton champ, et tu ne tailleras point ta vigne."},"en":{"prompt":"In the seventh year, what were they not to do to their field and vineyard?","bible_ref":"Leviticus 25:4","verse_text":"But in the seventh year shall be a sabbath of rest unto the land, a sabbath for the LORD: thou shalt neither sow thy field, nor prune thy vineyard."},"es":{"prompt":"En el séptimo año, ¿qué no debían hacer a su tierra y a su viña?","bible_ref":"Levítico 25:4","verse_text":"Y el séptimo año la tierra tendrá sábado de holganza, sábado á Jehová: no sembrarás tu tierra, ni podarás tu viña."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Semear e podar"},"fr":{"text":"Ensemencer et tailler"},"en":{"text":"Sow and prune"},"es":{"text":"Sembrar y podar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Regar e vender"},"fr":{"text":"Arroser et vendre"},"en":{"text":"Water and sell"},"es":{"text":"Regar y vender"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Medir e cercar"},"fr":{"text":"Mesurer et clôturer"},"en":{"text":"Measure and fence"},"es":{"text":"Medir y cercar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Comprar e herdar"},"fr":{"text":"Acheter et hériter"},"en":{"text":"Buy and inherit"},"es":{"text":"Comprar y heredar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-009","type":"choice","level":"medium","testament":"ot","book":"LEV","chapter":25,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Que ano devia ser santificado como jubileu?","bible_ref":"Levítico 25:10","verse_text":"E santificareis o ano cinquenta, e apregoareis liberdade na terra a todos os seus moradores: este vos será jubileu; e voltareis cada um à sua possessão, e cada qual voltará à sua família."},"fr":{"prompt":"Quelle année devait être sanctifiée comme jubilé ?","bible_ref":"Lévitique 25:10","verse_text":"Et vous sanctifierez la cinquantième année, vous publierez la liberté dans le pays pour tous ses habitants: ce sera pour vous le jubilé; chacun de vous retournera dans sa propriété, et chacun de vous retournera dans sa famille."},"en":{"prompt":"Which year was to be hallowed as a jubile?","bible_ref":"Leviticus 25:10","verse_text":"And ye shall hallow the fiftieth year, and proclaim liberty throughout all the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family."},"es":{"prompt":"¿Qué año debía santificarse como jubileo?","bible_ref":"Levítico 25:10","verse_text":"Y santificaréis el año cincuenta, y pregonaréis libertad en la tierra á todos sus moradores: éste os será jubileo; y volveréis cada uno á su posesión, y cada cual volverá á su familia."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O ano cinquenta"},"fr":{"text":"La cinquantième année"},"en":{"text":"The fiftieth year"},"es":{"text":"El año cincuenta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O sétimo ano"},"fr":{"text":"La septième année"},"en":{"text":"The seventh year"},"es":{"text":"El año séptimo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O ano quarenta"},"fr":{"text":"La quarantième année"},"en":{"text":"The fortieth year"},"es":{"text":"El año cuarenta"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O ano cem"},"fr":{"text":"La centième année"},"en":{"text":"The hundredth year"},"es":{"text":"El año cien"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-010","type":"choice","level":"medium","testament":"ot","book":"LEV","chapter":27,"verse_start":30,"verse_end":30,"texts":{"pt":{"prompt":"Segundo Levítico 27:30, a quem pertencem os dízimos da terra?","bible_ref":"Levítico 27:30","verse_text":"E todos os dízimos da terra, tanto das sementes da terra como dos frutos das árvores, pertencem ao SENHOR; são coisas consagradas ao SENHOR."},"fr":{"prompt":"D’après Lévitique 27:30, à qui appartient la dîme de la terre ?","bible_ref":"Lévitique 27:30","verse_text":"Toute dîme de la terre, soit des récoltes de la terre, soit du fruit des arbres, appartient à l’Éternel; c’est une chose consacrée à l’Éternel."},"en":{"prompt":"According to Leviticus 27:30, whose is the tithe of the land?","bible_ref":"Leviticus 27:30","verse_text":"And all the tithe of the land, whether of the seed of the land, or of the fruit of the tree, is the LORD’s: it is holy unto the LORD."},"es":{"prompt":"Según Levítico 27:30, ¿de quién son las décimas de la tierra?","bible_ref":"Levítico 27:30","verse_text":"Y todas las décimas de la tierra, así de la simiente de la tierra como del fruto de los árboles, de Jehová son: es cosa consagrada á Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ao SENHOR"},"fr":{"text":"À l’Éternel"},"en":{"text":"The LORD’s"},"es":{"text":"De Jehová"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ao rei"},"fr":{"text":"Au roi"},"en":{"text":"The king’s"},"es":{"text":"Del rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ao dono da terra"},"fr":{"text":"Au propriétaire du champ"},"en":{"text":"The landowner’s"},"es":{"text":"Del dueño de la tierra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Aos pobres"},"fr":{"text":"Aux pauvres"},"en":{"text":"The poor’s"},"es":{"text":"De los pobres"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-011","type":"choice","level":"medium","testament":"ot","book":"LEV","chapter":19,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Ao ceifar, que parte do campo não deviam acabar de ceifar?","bible_ref":"Levítico 19:9","verse_text":"Quando ceifardes na colheita de vossa terra, não acabarás de ceifar o canto de tua plantação, nem espigarás tua terra ceifada."},"fr":{"prompt":"Lors de la moisson, quelle partie du champ fallait-il laisser sans moissonner ?","bible_ref":"Lévitique 19:9","verse_text":"Quand vous ferez la moisson dans votre pays, tu laisseras un coin de ton champ sans le moissonner, et tu ne ramasseras pas ce qui reste à glaner."},"en":{"prompt":"When reaping, which part of the field were they not to wholly reap?","bible_ref":"Leviticus 19:9","verse_text":"And when ye reap the harvest of your land, thou shalt not wholly reap the corners of thy field, neither shalt thou gather the gleanings of thy harvest."},"es":{"prompt":"Al segar, ¿qué parte del campo no debían acabar de segar?","bible_ref":"Levítico 19:9","verse_text":"Cuando segareis la mies de vuestra tierra, no acabarás de segar el rincón de tu haza, ni espigarás tu tierra segada."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O canto"},"fr":{"text":"Un coin"},"en":{"text":"The corners"},"es":{"text":"El rincón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O centro"},"fr":{"text":"Le milieu"},"en":{"text":"The middle"},"es":{"text":"El centro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A entrada"},"fr":{"text":"L’entrée"},"en":{"text":"The entrance"},"es":{"text":"La entrada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A parte junto ao rio"},"fr":{"text":"La partie près du fleuve"},"en":{"text":"The part by the river"},"es":{"text":"La parte junto al río"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-012","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":6,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Durante o voto de nazireado, o que não podia passar sobre a cabeça?","bible_ref":"Números 6:5","verse_text":"Todo o tempo do voto de seu nazireado não passará navalha sobre sua cabeça, até que sejam cumpridos os dias de sua separação ao SENHOR: santo será; deixará crescer as pontas do cabelo de sua cabeça."},"fr":{"prompt":"Pendant le naziréat, qu’est-ce qui ne devait point passer sur la tête ?","bible_ref":"Nombres 6:5","verse_text":"Pendant tout le temps de son naziréat, le rasoir ne passera point sur sa tête; jusqu’à l’accomplissement des jours pour lesquels il s’est consacré à l’Éternel, il sera saint, il laissera croître librement ses cheveux."},"en":{"prompt":"During the vow of separation, what was not to come upon the head?","bible_ref":"Numbers 6:5","verse_text":"All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth himself unto the LORD, he shall be holy, and shall let the locks of the hair of his head grow."},"es":{"prompt":"Durante el voto de nazareato, ¿qué no debía pasar sobre la cabeza?","bible_ref":"Números 6:5","verse_text":"Todo el tiempo del voto de su nazareato no pasará navaja sobre su cabeza, hasta que sean cumplidos los días de su apartamiento á Jehová: santo será; dejará crecer las guedejas del cabello de su cabeza."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A navalha"},"fr":{"text":"Le rasoir"},"en":{"text":"A razor"},"es":{"text":"La navaja"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O azeite"},"fr":{"text":"L’huile"},"en":{"text":"Oil"},"es":{"text":"El aceite"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A água"},"fr":{"text":"L’eau"},"en":{"text":"Water"},"es":{"text":"El agua"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma coroa"},"fr":{"text":"Une couronne"},"en":{"text":"A crown"},"es":{"text":"Una corona"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-013","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":11,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Que aves trouxe o vento do SENHOR para junto do acampamento?","bible_ref":"Números 11:31","verse_text":"E saiu um vento do SENHOR, que trouxe codornizes do mar, e deixou-as sobre o acampamento, de um dia de caminho de um lado e do outro, ao redor do acampamento, e quase dois côvados sobre a face da terra."},"fr":{"prompt":"Quels oiseaux le vent envoyé par l’Éternel amena-t-il sur le camp ?","bible_ref":"Nombres 11:31","verse_text":"L’Éternel fit souffler de la mer un vent, qui amena des cailles, et les répandit sur le camp, environ une journée de chemin d’un côté et environ une journée de chemin de l’autre côté, autour du camp. Il y en avait près de deux coudées au-dessus de la surface de la terre."},"en":{"prompt":"What birds did the wind from the LORD bring by the camp?","bible_ref":"Numbers 11:31","verse_text":"And there went forth a wind from the LORD, and brought quails from the sea, and let them fall by the camp, as it were a day’s journey on this side, and as it were a day’s journey on the other side, round about the camp, and as it were two cubits high upon the face of the earth."},"es":{"prompt":"¿Qué aves trajo el viento de Jehová sobre el campamento?","bible_ref":"Números 11:31","verse_text":"Y salió un viento de Jehová, y trajo codornices de la mar, y dejólas sobre el real, un día de camino de la una parte, y un día de camino de la otra, en derredor del campo, y casi dos codos sobre la haz de la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Codornizes"},"fr":{"text":"Des cailles"},"en":{"text":"Quails"},"es":{"text":"Codornices"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pombas"},"fr":{"text":"Des colombes"},"en":{"text":"Doves"},"es":{"text":"Palomas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Corvos"},"fr":{"text":"Des corbeaux"},"en":{"text":"Ravens"},"es":{"text":"Cuervos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pardais"},"fr":{"text":"Des passereaux"},"en":{"text":"Sparrows"},"es":{"text":"Gorriones"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-014","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":12,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Como descreve Números 12:3 o homem Moisés?","bible_ref":"Números 12:3","verse_text":"Aquele homem Moisés era muito manso, mais que todos os homens que havia sobre a terra,"},"fr":{"prompt":"Comment Nombres 12:3 décrit-il Moïse ?","bible_ref":"Nombres 12:3","verse_text":"Et l’Éternel l’entendit. Or, Moïse était un homme fort patient, plus qu’aucun homme sur la face de la terre."},"en":{"prompt":"How does Numbers 12:3 describe the man Moses?","bible_ref":"Numbers 12:3","verse_text":"(Now the man Moses was very meek, above all the men which were upon the face of the earth.)"},"es":{"prompt":"¿Cómo describe Números 12:3 al varón Moisés?","bible_ref":"Números 12:3","verse_text":"Y aquel varón Moisés era muy manso, más que todos los hombres que había sobre la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mais manso do que todos os homens"},"fr":{"text":"Plus patient que tout homme"},"en":{"text":"Meek above all men"},"es":{"text":"Más manso que todos los hombres"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mais forte do que todos os homens"},"fr":{"text":"Plus fort que tout homme"},"en":{"text":"Strong above all men"},"es":{"text":"Más fuerte que todos los hombres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mais rico do que todos os homens"},"fr":{"text":"Plus riche que tout homme"},"en":{"text":"Rich above all men"},"es":{"text":"Más rico que todos los hombres"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Mais alto do que todos os homens"},"fr":{"text":"Plus grand que tout homme"},"en":{"text":"Tall above all men"},"es":{"text":"Más alto que todos los hombres"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-015","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":20,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Porque não levariam Moisés e Arão a congregação à terra prometida?","bible_ref":"Números 20:12","verse_text":"E o SENHOR disse a Moisés e a Arão: Porquanto não crestes em mim, para santificar-me aos olhos dos filhos de Israel, portanto, não poreis esta congregação na terra que lhes dei."},"fr":{"prompt":"Pourquoi Moïse et Aaron ne feraient-ils pas entrer l’assemblée dans le pays ?","bible_ref":"Nombres 20:12","verse_text":"Alors l’Éternel dit à Moïse et à Aaron: Parce que vous n’avez pas cru en moi, pour me sanctifier aux yeux des enfants d’Israël, vous ne ferez point entrer cette assemblée dans le pays que je lui donne."},"en":{"prompt":"Why would Moses and Aaron not bring the congregation into the land?","bible_ref":"Numbers 20:12","verse_text":"And the LORD spake unto Moses and Aaron, Because ye believed me not, to sanctify me in the eyes of the children of Israel, therefore ye shall not bring this congregation into the land which I have given them."},"es":{"prompt":"¿Por qué Moisés y Aarón no meterían la congregación en la tierra?","bible_ref":"Números 20:12","verse_text":"Y Jehová dijo á Moisés y á Aarón: Por cuanto no creísteis en mí, para santificarme en ojos de los hijos de Israel, por tanto, no meteréis esta congregación en la tierra que les he dado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Porque não creram no SENHOR"},"fr":{"text":"Parce qu’ils n’avaient pas cru en l’Éternel"},"en":{"text":"Because they believed not the LORD"},"es":{"text":"Porque no creyeron en Jehová"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Porque eram velhos demais"},"fr":{"text":"Parce qu’ils étaient trop vieux"},"en":{"text":"Because they were too old"},"es":{"text":"Porque eran demasiado viejos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Porque tinham medo dos gigantes"},"fr":{"text":"Parce qu’ils avaient peur des géants"},"en":{"text":"Because they feared the giants"},"es":{"text":"Porque temían a los gigantes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Porque o povo não os queria"},"fr":{"text":"Parce que le peuple ne voulait plus d’eux"},"en":{"text":"Because the people rejected them"},"es":{"text":"Porque el pueblo no los quería"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-016","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":11,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Quantos anciãos de Israel mandou o SENHOR Moisés reunir?","bible_ref":"Números 11:16","verse_text":"Então o SENHOR disse a Moisés: Ajunta-me setenta homens dos anciãos de Israel, de quem sabes que são anciãos do povo, e seus oficiais; e traze-os à porta do tabernáculo do testemunho, e esperem ali contigo."},"fr":{"prompt":"Combien d’anciens d’Israël l’Éternel dit-il à Moïse d’assembler ?","bible_ref":"Nombres 11:16","verse_text":"L’Éternel dit à Moïse: Assemble auprès de moi soixante-dix hommes des anciens d’Israël, de ceux que tu connais comme anciens du peuple et ayant autorité sur lui; amène-les à la tente d’assignation, et qu’ils s’y présentent avec toi."},"en":{"prompt":"How many of the elders of Israel did the LORD tell Moses to gather?","bible_ref":"Numbers 11:16","verse_text":"And the LORD said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee."},"es":{"prompt":"¿Cuántos ancianos de Israel mandó Jehová a Moisés juntar?","bible_ref":"Números 11:16","verse_text":"Entonces Jehová dijo á Moisés: Júntame setenta varones de los ancianos de Israel, que tú sabes que son ancianos del pueblo y sus principales; y tráelos á la puerta del tabernáculo del testimonio, y esperen allí contigo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"70"},"fr":{"text":"70"},"en":{"text":"70"},"es":{"text":"70"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"12"},"fr":{"text":"12"},"en":{"text":"12"},"es":{"text":"12"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"40"},"fr":{"text":"40"},"en":{"text":"40"},"es":{"text":"40"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"120"},"fr":{"text":"120"},"en":{"text":"120"},"es":{"text":"120"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-017","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":1,"verse_start":49,"verse_end":49,"texts":{"pt":{"prompt":"Que tribo não devia ser contada no recenseamento dos filhos de Israel?","bible_ref":"Números 1:49","verse_text":"Somente não contarás a tribo de Levi, nem tomarás a conta deles entre os filhos de Israel:"},"fr":{"prompt":"Quelle tribu ne devait pas être comptée dans le dénombrement des enfants d’Israël ?","bible_ref":"Nombres 1:49","verse_text":"Tu ne feras point le dénombrement de la tribu de Lévi, et tu n’en compteras point les têtes au milieu des enfants d’Israël."},"en":{"prompt":"Which tribe was not to be numbered among the children of Israel?","bible_ref":"Numbers 1:49","verse_text":"Only thou shalt not number the tribe of Levi, neither take the sum of them among the children of Israel:"},"es":{"prompt":"¿Qué tribu no debía contarse entre los hijos de Israel?","bible_ref":"Números 1:49","verse_text":"Solamente no contarás la tribu de Leví, ni tomarás la cuenta de ellos entre los hijos de Israel:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Levi"},"fr":{"text":"Lévi"},"en":{"text":"Levi"},"es":{"text":"Leví"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Judá"},"fr":{"text":"Juda"},"en":{"text":"Judah"},"es":{"text":"Judá"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Rúben"},"fr":{"text":"Ruben"},"en":{"text":"Reuben"},"es":{"text":"Rubén"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Benjamim"},"fr":{"text":"Benjamin"},"en":{"text":"Benjamin"},"es":{"text":"Benjamín"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-018","type":"choice","level":"medium","testament":"ot","book":"DEU","chapter":34,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Deuteronómio 34:10, como conhecia o SENHOR a Moisés?","bible_ref":"Deuteronómio 34:10","verse_text":"E nunca mais se levantou profeta em Israel como Moisés, a quem haja conhecido o SENHOR face a face;"},"fr":{"prompt":"D’après Deutéronome 34:10, comment l’Éternel connaissait-il Moïse ?","bible_ref":"Deutéronome 34:10","verse_text":"Il n’a plus paru en Israël de prophète semblable à Moïse, que l’Éternel connaissait face à face."},"en":{"prompt":"According to Deuteronomy 34:10, how did the LORD know Moses?","bible_ref":"Deuteronomy 34:10","verse_text":"And there arose not a prophet since in Israel like unto Moses, whom the LORD knew face to face,"},"es":{"prompt":"Según Deuteronomio 34:10, ¿cómo conocía Jehová a Moisés?","bible_ref":"Deuteronomio 34:10","verse_text":"Y nunca más se levantó profeta en Israel como Moisés, á quien haya conocido Jehová cara á cara;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Face a face"},"fr":{"text":"Face à face"},"en":{"text":"Face to face"},"es":{"text":"Cara a cara"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em sonhos"},"fr":{"text":"En songe"},"en":{"text":"In dreams"},"es":{"text":"En sueños"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Por meio de anjos"},"fr":{"text":"Par des anges"},"en":{"text":"Through angels"},"es":{"text":"Por medio de ángeles"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Só de longe"},"fr":{"text":"Seulement de loin"},"en":{"text":"Only from afar"},"es":{"text":"Solo de lejos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-019","type":"choice","level":"medium","testament":"ot","book":"DEU","chapter":34,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Deuteronómio 34:6, quem conhece o sepulcro de Moisés?","bible_ref":"Deuteronómio 34:6","verse_text":"E enterrou-o no vale, em terra de Moabe, em frente de Bete-Peor; e ninguém sabe seu sepulcro até hoje."},"fr":{"prompt":"D’après Deutéronome 34:6, qui connaît le sépulcre de Moïse ?","bible_ref":"Deutéronome 34:6","verse_text":"Et l’Éternel l’enterra dans la vallée, au pays de Moab, vis-à-vis de Beth-Peor. Personne n’a connu son sépulcre jusqu’à ce jour."},"en":{"prompt":"According to Deuteronomy 34:6, who knows of Moses’ sepulchre?","bible_ref":"Deuteronomy 34:6","verse_text":"And he buried him in a valley in the land of Moab, over against Beth-peor: but no man knoweth of his sepulchre unto this day."},"es":{"prompt":"Según Deuteronomio 34:6, ¿quién sabe el sepulcro de Moisés?","bible_ref":"Deuteronomio 34:6","verse_text":"Y enterrólo en el valle, en tierra de Moab, enfrente de Bethpeor; y ninguno sabe su sepulcro hasta hoy."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ninguém, até hoje"},"fr":{"text":"Personne, jusqu’à ce jour"},"en":{"text":"No man, unto this day"},"es":{"text":"Ninguno, hasta hoy"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Só Josué"},"fr":{"text":"Seulement Josué"},"en":{"text":"Only Joshua"},"es":{"text":"Solo Josué"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os sacerdotes"},"fr":{"text":"Les sacrificateurs"},"en":{"text":"The priests"},"es":{"text":"Los sacerdotes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Toda a tribo de Levi"},"fr":{"text":"Toute la tribu de Lévi"},"en":{"text":"All the tribe of Levi"},"es":{"text":"Toda la tribu de Leví"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-020","type":"choice","level":"medium","testament":"ot","book":"DEU","chapter":25,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"O que não se devia pôr ao boi quando trilhava o grão?","bible_ref":"Deuteronómio 25:4","verse_text":"Não porás mordaça ao boi quando trilhar."},"fr":{"prompt":"Que ne fallait-il pas mettre au bœuf quand il foulait le grain ?","bible_ref":"Deutéronome 25:4","verse_text":"Tu n’emmuselleras point le bœuf, quand il foulera le grain."},"en":{"prompt":"What was not to be put on the ox when he treadeth out the corn?","bible_ref":"Deuteronomy 25:4","verse_text":"Thou shalt not muzzle the ox when he treadeth out the corn."},"es":{"prompt":"¿Qué no se debía poner al buey cuando trillaba?","bible_ref":"Deuteronomio 25:4","verse_text":"No pondrás bozal al buey cuando trillare."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma mordaça"},"fr":{"text":"Une muselière"},"en":{"text":"A muzzle"},"es":{"text":"Un bozal"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um jugo"},"fr":{"text":"Un joug"},"en":{"text":"A yoke"},"es":{"text":"Un yugo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um sino"},"fr":{"text":"Une clochette"},"en":{"text":"A bell"},"es":{"text":"Una campana"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma corda"},"fr":{"text":"Une corde"},"en":{"text":"A rope"},"es":{"text":"Una cuerda"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-021","type":"choice","level":"medium","testament":"ot","book":"DEU","chapter":28,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Deuteronómio 28:13, se o povo obedecesse, o SENHOR pô-lo-ia por cabeça e não por…","bible_ref":"Deuteronómio 28:13","verse_text":"E te porá o SENHOR por cabeça, e não por cauda: e estarás encima somente, e não estarás debaixo; quando obedeceres aos mandamentos do SENHOR teu Deus, que eu te ordeno hoje, para que os guardes e cumpras."},"fr":{"prompt":"D’après Deutéronome 28:13, si le peuple obéissait, l’Éternel ferait de lui la tête et non…","bible_ref":"Deutéronome 28:13","verse_text":"L’Éternel fera de toi la tête et non la queue, tu seras toujours en haut et tu ne seras jamais en bas, lorsque tu obéiras aux commandements de l’Éternel, ton Dieu, que je te prescris aujourd’hui, lorsque tu les observeras et les mettras en pratique,"},"en":{"prompt":"According to Deuteronomy 28:13, if the people obeyed, the LORD would make them the head and not…","bible_ref":"Deuteronomy 28:13","verse_text":"And the LORD shall make thee the head, and not the tail; and thou shalt be above only, and thou shalt not be beneath; if that thou hearken unto the commandments of the LORD thy God, which I command thee this day, to observe and to do them:"},"es":{"prompt":"Según Deuteronomio 28:13, si el pueblo obedecía, Jehová lo pondría por cabeza y no por…","bible_ref":"Deuteronomio 28:13","verse_text":"Y te pondrá Jehová por cabeza, y no por cola: y estarás encima solamente, y no estarás debajo; cuando obedecieres á los mandamientos de Jehová tu Dios, que yo te ordeno hoy, para que los guardes y cumplas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cauda"},"fr":{"text":"La queue"},"en":{"text":"The tail"},"es":{"text":"Cola"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pés"},"fr":{"text":"Les pieds"},"en":{"text":"The feet"},"es":{"text":"Pies"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Servo"},"fr":{"text":"Le serviteur"},"en":{"text":"The servant"},"es":{"text":"Siervo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Último"},"fr":{"text":"Le dernier"},"en":{"text":"The last"},"es":{"text":"Último"}}}]}$json$::jsonb);
