select public.upsert_bank_question($json${"id":"lei2-medium-034","type":"verse","level":"medium","testament":"ot","book":"DEU","chapter":30,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Aos céus e a terra chamo por testemunhas hoje contra vós, que pus diante de vós a vida e a morte, a bênção e a maldição: _____, pois, a vida, para que vivas tu e tua descendência:","bible_ref":"Deuteronómio 30:19","verse_text":"Aos céus e a terra chamo por testemunhas hoje contra vós, que pus diante de vós a vida e a morte, a bênção e a maldição: escolhe, pois, a vida, para que vivas tu e tua descendência:"},"fr":{"prompt":"J’en prends aujourd’hui à témoin contre vous le ciel et la terre: j’ai mis devant toi la vie et la mort, la bénédiction et la malédiction. _____ la vie, afin que tu vives, toi et ta postérité,","bible_ref":"Deutéronome 30:19","verse_text":"J’en prends aujourd’hui à témoin contre vous le ciel et la terre: j’ai mis devant toi la vie et la mort, la bénédiction et la malédiction. Choisis la vie, afin que tu vives, toi et ta postérité,"},"en":{"prompt":"I call heaven and earth to record this day against you, that I have set before you life and death, blessing and cursing: therefore _____ life, that both thou and thy seed may live:","bible_ref":"Deuteronomy 30:19","verse_text":"I call heaven and earth to record this day against you, that I have set before you life and death, blessing and cursing: therefore choose life, that both thou and thy seed may live:"},"es":{"prompt":"A los cielos y la tierra llamo por testigos hoy contra vosotros, que os he puesto delante la vida y la muerte, la bendición y la maldición: _____ pues la vida, porque vivas tú y tu simiente:","bible_ref":"Deuteronomio 30:19","verse_text":"A los cielos y la tierra llamo por testigos hoy contra vosotros, que os he puesto delante la vida y la muerte, la bendición y la maldición: escoge pues la vida, porque vivas tú y tu simiente:"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"esquece"},"fr":{"text":"Oublie"},"en":{"text":"forget"},"es":{"text":"olvida"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"teme"},"fr":{"text":"Crains"},"en":{"text":"fear"},"es":{"text":"teme"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"vende"},"fr":{"text":"Vends"},"en":{"text":"sell"},"es":{"text":"vende"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"escolhe"},"fr":{"text":"Choisis"},"en":{"text":"choose"},"es":{"text":"escoge"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-medium-035","type":"verse","level":"medium","testament":"ot","book":"DEU","chapter":33,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"O eterno Deus é o teu refúgio, e abaixo os _____ eternos; ele expulsará de diante de ti o inimigo, e dirá: Destrói.","bible_ref":"Deuteronómio 33:27","verse_text":"O eterno Deus é o teu refúgio, e abaixo os braços eternos; ele expulsará de diante de ti o inimigo, e dirá: Destrói."},"fr":{"prompt":"Le Dieu d’éternité est un refuge, Et sous ses _____ Éternels est une retraite. Devant toi il a chassé l’ennemi, Et il a dit: Extermine.","bible_ref":"Deutéronome 33:27","verse_text":"Le Dieu d’éternité est un refuge, Et sous ses bras Éternels est une retraite. Devant toi il a chassé l’ennemi, Et il a dit: Extermine."},"en":{"prompt":"The eternal God is thy refuge, and underneath are the everlasting _____: and he shall thrust out the enemy from before thee; and shall say, Destroy them.","bible_ref":"Deuteronomy 33:27","verse_text":"The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them."},"es":{"prompt":"El eterno Dios es tu refugio, y acá abajo los _____ eternos; él echará de delante de ti al enemigo, y dirá: Destruye.","bible_ref":"Deuteronomio 33:27","verse_text":"El eterno Dios es tu refugio, y acá abajo los brazos eternos; él echará de delante de ti al enemigo, y dirá: Destruye."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"montes"},"fr":{"text":"monts"},"en":{"text":"hills"},"es":{"text":"montes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"olhos"},"fr":{"text":"yeux"},"en":{"text":"eyes"},"es":{"text":"ojos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"pés"},"fr":{"text":"pieds"},"en":{"text":"feet"},"es":{"text":"pies"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"braços"},"fr":{"text":"bras"},"en":{"text":"arms"},