select public.upsert_bank_question($json${"id":"lei2-hard-001","type":"choice","level":"hard","testament":"ot","book":"GEN","chapter":35,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Ao morrer, que nome deu Raquel ao filho que lhe nasceu?","bible_ref":"Génesis 35:18","verse_text":"E aconteceu que ao sair dela a alma, (pois morreu) chamou seu nome Benoni; mas seu pai o chamou Benjamim."},"fr":{"prompt":"En mourant, quel nom Rachel donna-t-elle au fils qui venait de naître ?","bible_ref":"Genèse 35:18","verse_text":"Et comme elle allait rendre l’âme, car elle était mourante, elle lui donna le nom de Ben-Oni; mais le père l’appela Benjamin."},"en":{"prompt":"As she was dying, what name did Rachel give the son just born?","bible_ref":"Genesis 35:18","verse_text":"And it came to pass, as her soul was in departing, (for she died) that she called his name Ben-oni: but his father called him Benjamin."},"es":{"prompt":"Al morir, ¿qué nombre dio Rachêl al hijo que le nació?","bible_ref":"Génesis 35:18","verse_text":"Y acaeció que al salírsele el alma, (pues murió) llamó su nombre Benoni; mas su padre lo llamó Benjamín."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Benoni"},"fr":{"text":"Ben-Oni"},"en":{"text":"Ben-oni"},"es":{"text":"Benoni"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rúben"},"fr":{"text":"Ruben"},"en":{"text":"Reuben"},"es":{"text":"Rubén"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Judá"},"fr":{"text":"Juda"},"en":{"text":"Judah"},"es":{"text":"Judá"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Gade"},"fr":{"text":"Gad"},"en":{"text":"Gad"},"es":{"text":"Gad"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-002","type":"choice","level":"hard","testament":"ot","book":"GEN","chapter":32,"verse_start":30,"verse_end":30,"texts":{"pt":{"prompt":"Que nome deu Jacob ao lugar onde viu Deus face a face?","bible_ref":"Génesis 32:30","verse_text":"E chamou Jacó o nome daquele lugar Peniel: porque vi a Deus face a face, e foi livrada minha alma."},"fr":{"prompt":"Quel nom Jacob donna-t-il au lieu où il vit Dieu face à face ?","bible_ref":"Genèse 32:30","verse_text":"Jacob appela ce lieu du nom de Peniel: car, dit-il, j’ai vu Dieu face à face, et mon âme a été sauvée."},"en":{"prompt":"What did Jacob call the place where he saw God face to face?","bible_ref":"Genesis 32:30","verse_text":"And Jacob called the name of the place Peniel: for I have seen God face to face, and my life is preserved."},"es":{"prompt":"¿Qué nombre puso Jacob al lugar donde vio a Dios cara a cara?","bible_ref":"Génesis 32:30","verse_text":"Y llamó Jacob el nombre de aquel lugar, Peniel: porque vi á Dios cara á cara, y fué librada mi alma."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Peniel"},"fr":{"text":"Peniel"},"en":{"text":"Peniel"},"es":{"text":"Peniel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Betel"},"fr":{"text":"Béthel"},"en":{"text":"Beth-el"},"es":{"text":"Beth-el"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Berseba"},"fr":{"text":"Beer-Schéba"},"en":{"text":"Beer-sheba"},"es":{"text":"Beer-seba"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Hebrom"},"fr":{"text":"Hébron"},"en":{"text":"Hebron"},"es":{"text":"Hebrón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-003","type":"choice","level":"hard","testament":"ot","book":"EXO","chapter":1,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Como se chamavam as parteiras das hebreias a quem falou o rei do Egito?","bible_ref":"Êxodo 1:15","verse_text":"E o rei do Egito falou às parteiras das hebreias, uma das quais se chamava Sifrá, e outra Puá, e disse-lhes:"},"fr":{"prompt":"Comment s’appelaient les sages-femmes des Hébreux à qui parla le roi d’Égypte ?","bible_ref":"Exode 1:15","verse_text":"Le roi d’Égypte parla aussi aux sages-femmes des Hébreux, nommées l’une Schiphra, et l’autre Pua."},"en":{"prompt":"What were the names of the Hebrew midwives the king of Egypt spoke to?","bible_ref":"Exodus 1:15","verse_text":"And the king of Egypt spake to the Hebrew midwives, of which the name of the one was Shiphrah, and the name of the other Puah:"},"es":{"prompt":"¿Cómo se llamaban las parteras de las Hebreas a quienes habló el rey de Egipto?","bible_ref":"Éxodo 1:15","verse_text":"Y habló el rey de Egipto á las parteras de las Hebreas, una de las cuales se llamaba Siphra, y otra Phúa, y díjoles:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sifrá e Puá"},"fr":{"text":"Schiphra et Pua"},"en":{"text":"Shiphrah and Puah"},"es":{"text":"Siphra y Phúa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ada e Zilá"},"fr":{"text":"Ada et Tsilla"},"en":{"text":"Adah and Zillah"},"es":{"text":"Ada y Zilla"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Bila e Zilpa"},"fr":{"text":"Bilha et Zilpa"},"en":{"text":"Bilhah and Zilpah"},"es":{"text":"Bilha y Zilpa"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lia e Raquel"},"fr":{"text":"Léa et Rachel"},"en":{"text":"Leah and Rachel"},"es":{"text":"Lea y Rachêl"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-004","type":"choice","level":"hard","testament":"ot","book":"EXO","chapter":15,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"O que havia em Elim, onde Israel acampou junto às águas?","bible_ref":"Êxodo 15:27","verse_text":"E chegaram a Elim, onde havia doze fontes de águas, e setenta palmeiras; e assentaram ali junto às águas."},"fr":{"prompt":"Qu’y avait-il à Élim, où Israël campa près de l’eau ?","bible_ref":"Exode 15:27","verse_text":"Ils arrivèrent à Élim, où il y avait douze sources d’eau et soixante-dix palmiers. Ils campèrent là, près de l’eau."},"en":{"prompt":"What was at Elim, where Israel encamped by the waters?","bible_ref":"Exodus 15:27","verse_text":"And they came to Elim, where were twelve wells of water, and threescore and ten palm trees: and they encamped there by the waters."},"es":{"prompt":"¿Qué había en Elim, donde Israel asentó junto a las aguas?","bible_ref":"Éxodo 15:27","verse_text":"Y llegaron á Elim, donde había doce fuentes de aguas, y setenta palmas; y asentaron allí junto á las aguas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"12 fontes e 70 palmeiras"},"fr":{"text":"12 sources et 70 palmiers"},"en":{"text":"12 wells and 70 palm trees"},"es":{"text":"12 fuentes y 70 palmas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"7 poços e 40 figueiras"},"fr":{"text":"7 puits et 40 figuiers"},"en":{"text":"7 wells and 40 fig trees"},"es":{"text":"7 pozos y 40 higueras"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"3 fontes e 12 oliveiras"},"fr":{"text":"3 sources et 12 oliviers"},"en":{"text":"3 wells and 12 olive trees"},"es":{"text":"3 fuentes y 12 olivos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"12 poços e 12 videiras"},"fr":{"text":"12 puits et 12 vignes"},"en":{"text":"12 wells and 12 vines"},"es":{"text":"12 pozos y 12 vides"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-005","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":10,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"O que não podiam beber Arão e os filhos quando entravam no tabernáculo?","bible_ref":"Levítico 10:9","verse_text":"Tu, e teus filhos contigo, não bebereis vinho nem bebida forte, quando houverdes de entrar no tabernáculo do testemunho, para que não morrais: estatuto perpétuo por vossas gerações;"},"fr":{"prompt":"Que ne devaient pas boire Aaron et ses fils quand ils entraient dans la tente d’assignation ?","bible_ref":"Lévitique 10:9","verse_text":"Tu ne boiras ni vin, ni boisson enivrante, toi et tes fils avec toi, lorsque vous entrerez dans la tente d’assignation, de peur que vous ne mouriez: ce sera une loi perpétuelle parmi vos descendants,"},"en":{"prompt":"What were Aaron and his sons not to drink when they went into the tabernacle?","bible_ref":"Leviticus 10:9","verse_text":"Do not drink wine nor strong drink, thou, nor thy sons with thee, when ye go into the tabernacle of the congregation, lest ye die: it shall be a statute for ever throughout your generations:"},"es":{"prompt":"¿Qué no podían beber Aarón y sus hijos cuando entraban en el tabernáculo?","bible_ref":"Levítico 10:9","verse_text":"Tú, y tus hijos contigo, no beberéis vino ni sidra, cuando hubiereis de entrar en el tabernáculo del testimonio, porque no muráis: estatuto perpetuo por vuestras generaciones;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vinho nem bebida forte"},"fr":{"text":"Ni vin ni boisson enivrante"},"en":{"text":"Wine nor strong drink"},"es":{"text":"Vino ni sidra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Leite nem mel"},"fr":{"text":"Ni lait ni miel"},"en":{"text":"Milk nor honey"},"es":{"text":"Leche ni miel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Água nem leite"},"fr":{"text":"Ni eau ni lait"},"en":{"text":"Water nor milk"},"es":{"text":"Agua ni leche"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Azeite nem vinagre"},"fr":{"text":"Ni huile ni vinaigre"},"en":{"text":"Oil nor vinegar"},"es":{"text":"Aceite ni vinagre"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-006","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":23,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Em que dia do primeiro mês era a Páscoa do SENHOR?","bible_ref":"Levítico 23:5","verse_text":"No mês primeiro, aos catorze do mês, entre as duas tardes, páscoa é do SENHOR."},"fr":{"prompt":"Quel jour du premier mois était la Pâque de l’Éternel ?","bible_ref":"Lévitique 23:5","verse_text":"Le premier mois, le quatorzième jour du mois, entre les deux soirs, ce sera la Pâque de l’Éternel."},"en":{"prompt":"On which day of the first month was the LORD’s passover?","bible_ref":"Leviticus 23:5","verse_text":"In the fourteenth day of the first month at even is the LORD’s passover."},"es":{"prompt":"¿En qué día del mes primero era la pascua de Jehová?","bible_ref":"Levítico 23:5","verse_text":"En el mes primero, á los catorce del mes, entre las dos tardes, pascua es de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No dia 14"},"fr":{"text":"Le 14e jour"},"en":{"text":"On the 14th day"},"es":{"text":"El día 14"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No dia 10"},"fr":{"text":"Le 10e jour"},"en":{"text":"On the 10th day"},"es":{"text":"El día 10"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No dia 15"},"fr":{"text":"Le 15e jour"},"en":{"text":"On the 15th day"},"es":{"text":"El día 15"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No dia 7"},"fr":{"text":"Le 7e jour"},"en":{"text":"On the 7th day"},"es":{"text":"El día 7"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-007","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":16,"verse_start":29,"verse_end":29,"texts":{"pt":{"prompt":"Em Levítico 16:29, em que dia deviam afligir as almas e não fazer obra alguma?","bible_ref":"Levítico 16:29","verse_text":"E isto tereis por estatuto perpétuo: No mês sétimo, aos dez do mês, afligireis vossas almas, e nenhuma obra fareis, nem o natural nem o estrangeiro que peregrina entre vós:"},"fr":{"prompt":"En Lévitique 16:29, quel jour fallait-il humilier son âme et ne faire aucun ouvrage ?","bible_ref":"Lévitique 16:29","verse_text":"C’est ici pour vous une loi perpétuelle: au septième mois, le dixième jour du mois, vous humilierez vos âmes, vous ne ferez aucun ouvrage, ni l’indigène, ni l’étranger qui séjourne au milieu de vous."},"en":{"prompt":"In Leviticus 16:29, on which day were they to afflict their souls and do no work?","bible_ref":"Leviticus 16:29","verse_text":"And this shall be a statute for ever unto you: that in the seventh month, on the tenth day of the month, ye shall afflict your souls, and do no work at all, whether it be one of your own country, or a stranger that sojourneth among you:"},"es":{"prompt":"En Levítico 16:29, ¿qué día debían afligir sus almas y no hacer obra alguna?","bible_ref":"Levítico 16:29","verse_text":"Y esto tendréis por estatuto perpetuo: En el mes séptimo, á los diez del mes, afligiréis vuestras almas, y ninguna obra haréis, ni el natural ni el extranjero que peregrina entre vosotros:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dia 10 do sétimo mês"},"fr":{"text":"Le 10e jour du septième mois"},"en":{"text":"The 10th day of the seventh month"},"es":{"text":"El día 10 del mes séptimo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dia 14 do primeiro mês"},"fr":{"text":"Le 14e jour du premier mois"},"en":{"text":"The 14th day of the first month"},"es":{"text":"El día 14 del mes primero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dia 15 do sétimo mês"},"fr":{"text":"Le 15e jour du septième mois"},"en":{"text":"The 15th day of the seventh month"},"es":{"text":"El día 15 del mes séptimo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Dia 1 do sétimo mês"},"fr":{"text":"Le 1er jour du septième mois"},"en":{"text":"The 1st day of the seventh month"},"es":{"text":"El día 1 del mes séptimo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-008","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":2,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Levítico 2:13, o que devia ser oferecido com todas as ofertas?","bible_ref":"Levítico 2:13","verse_text":"E temperarás toda oferta de teu presente com sal; e não farás que falte jamais da tua oferta de alimentos o sal da aliança de teu Deus; em toda oferta tua oferecerás sal."},"fr":{"prompt":"D’après Lévitique 2:13, que fallait-il mettre sur toutes les offrandes ?","bible_ref":"Lévitique 2:13","verse_text":"Tu mettras du sel sur toutes tes offrandes; tu ne laisseras point ton offrande manquer de sel, signe de l’alliance de ton Dieu; sur toutes tes offrandes tu mettras du sel."},"en":{"prompt":"According to Leviticus 2:13, what was to be offered with all the offerings?","bible_ref":"Leviticus 2:13","verse_text":"And every oblation of thy meat offering shalt thou season with salt; neither shalt thou suffer the salt of the covenant of thy God to be lacking from thy meat offering: with all thine offerings thou shalt offer salt."},"es":{"prompt":"Según Levítico 2:13, ¿qué debía ofrecerse con toda ofrenda?","bible_ref":"Levítico 2:13","verse_text":"Y sazonarás toda ofrenda de tu presente con sal; y no harás que falte jamás de tu presente la sal de la alianza de tu Dios: en toda ofrenda tuya ofrecerás sal."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sal"},"fr":{"text":"Du sel"},"en":{"text":"Salt"},"es":{"text":"Sal"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mel"},"fr":{"text":"Du miel"},"en":{"text":"Honey"},"es":{"text":"Miel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Fermento"},"fr":{"text":"Du levain"},"en":{"text":"Leaven"},"es":{"text":"Levadura"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Vinagre"},"fr":{"text":"Du vinaigre"},"en":{"text":"Vinegar"},"es":{"text":"Vinagre"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-009","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":5,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Levítico 5:7, o que trazia pelo pecado quem não podia oferecer um animal do rebanho?","bible_ref":"Levítico 5:7","verse_text":"E se não lhe alcançar para um cordeiro, trará em expiação por seu pecado que cometeu, duas rolinhas ou dois pombinhos ao SENHOR; um para expiação, e o outro para holocausto."},"fr":{"prompt":"D’après Lévitique 5:7, qu’apportait pour son péché celui qui ne pouvait offrir une bête du troupeau ?","bible_ref":"Lévitique 5:7","verse_text":"S’il n’a pas de quoi se procurer une brebis ou une chèvre, il offrira en sacrifice de culpabilité à l’Éternel pour son péché deux tourterelles ou deux jeunes pigeons, l’un comme victime expiatoire, l’autre comme holocauste."},"en":{"prompt":"According to Leviticus 5:7, what did one bring for sin if he could not bring a lamb?","bible_ref":"Leviticus 5:7","verse_text":"And if he be not able to bring a lamb, then he shall bring for his trespass, which he hath committed, two turtledoves, or two young pigeons, unto the LORD; one for a sin offering, and the other for a burnt offering."},"es":{"prompt":"Según Levítico 5:7, ¿qué traía por su pecado quien no alcanzaba para un cordero?","bible_ref":"Levítico 5:7","verse_text":"Y si no le alcanzare para un cordero, traerá en expiación por su pecado que cometió, dos tórtolas ó dos palominos á Jehová; el uno para expiación, y el otro para holocausto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Duas rolinhas ou dois pombinhos"},"fr":{"text":"Deux tourterelles ou deux jeunes pigeons"},"en":{"text":"Two turtledoves or two young pigeons"},"es":{"text":"Dos tórtolas o dos palominos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um bezerro"},"fr":{"text":"Un veau"},"en":{"text":"A calf"},"es":{"text":"Un becerro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um carneiro"},"fr":{"text":"Un bélier"},"en":{"text":"A ram"},"es":{"text":"Un carnero"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Duas ovelhas"},"fr":{"text":"Deux brebis"},"en":{"text":"Two ewes"},"es":{"text":"Dos ovejas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-010","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":11,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Que dois homens ficaram no acampamento e ali profetizaram?","bible_ref":"Números 11:26","verse_text":"Porém ficaram no acampamento dois homens, um chamado Eldade e o outro Medade, sobre os quais o espírito também repousou (porque estavam entre os inscritos, mas não haviam saído à tenda); e profetizaram no acampamento."},"fr":{"prompt":"Quels deux hommes restèrent dans le camp et y prophétisèrent ?","bible_ref":"Nombres 11:26","verse_text":"Il y eut deux hommes, l’un appelé Eldad, et l’autre Médad, qui étaient restés dans le camp, et sur lesquels l’esprit reposa; car ils étaient parmi les inscrits, quoiqu’ils ne fussent point allés à la tente; et ils prophétisèrent dans le camp."},"en":{"prompt":"Which two men remained in the camp and prophesied there?","bible_ref":"Numbers 11:26","verse_text":"But there remained two of the men in the camp, the name of the one was Eldad, and the name of the other Medad: and the spirit rested upon them; and they were of them that were written, but went not out unto the tabernacle: and they prophesied in the camp."},"es":{"prompt":"¿Qué dos varones quedaron en el campamento y profetizaron allí?","bible_ref":"Números 11:26","verse_text":"Y habían quedado en el campo dos varones, llamado el uno Eldad y el otro Medad, sobre los cuales también reposó el espíritu: estaban estos entre los escritos, mas no habían salido al tabernáculo; y profetizaron en el campo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Eldade e Medade"},"fr":{"text":"Eldad et Médad"},"en":{"text":"Eldad and Medad"},"es":{"text":"Eldad y Medad"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nadabe e Abiú"},"fr":{"text":"Nadab et Abihu"},"en":{"text":"Nadab and Abihu"},"es":{"text":"Nadab y Abiú"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Datã e Abirão"},"fr":{"text":"Dathan et Abiram"},"en":{"text":"Dathan and Abiram"},"es":{"text":"Dathán y Abiram"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josué e Calebe"},"fr":{"text":"Josué et Caleb"},"en":{"text":"Joshua and Caleb"},"es":{"text":"Josué y Caleb"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-011","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":20,"verse_start":28,"verse_end":28,"texts":{"pt":{"prompt":"A quem vestiu Moisés as vestes de Arão, antes de Arão morrer no cume do monte?","bible_ref":"Números 20:28","verse_text":"E Moisés fez desnudar a Arão de suas roupas e vestiu-as a Eleazar seu filho: e Arão morreu ali no cume do monte: e Moisés e Eleazar desceram do monte."},"fr":{"prompt":"À qui Moïse fit-il revêtir les vêtements d’Aaron, avant qu’Aaron meure au sommet de la montagne ?","bible_ref":"Nombres 20:28","verse_text":"Moïse dépouilla Aaron de ses vêtements, et les fit revêtir à Éléazar, son fils. Aaron mourut là, au sommet de la montagne. Moïse et Éléazar descendirent de la montagne."},"en":{"prompt":"Upon whom did Moses put Aaron’s garments, before Aaron died in the top of the mount?","bible_ref":"Numbers 20:28","verse_text":"And Moses stripped Aaron of his garments, and put them upon Eleazar his son; and Aaron died there in the top of the mount: and Moses and Eleazar came down from the mount."},"es":{"prompt":"¿A quién vistió Moisés los vestidos de Aarón, antes de que Aarón muriera en la cumbre del monte?","bible_ref":"Números 20:28","verse_text":"Y Moisés hizo desnudar á Aarón de sus vestidos y vistiólos á Eleazar su hijo: y Aarón murió allí en la cumbre del monte: y Moisés y Eleazar descendieron del monte."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Eleazar"},"fr":{"text":"Éléazar"},"en":{"text":"Eleazar"},"es":{"text":"Eleazar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Itamar"},"fr":{"text":"Ithamar"},"en":{"text":"Ithamar"},"es":{"text":"Ithamar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fineias"},"fr":{"text":"Phinées"},"en":{"text":"Phinehas"},"es":{"text":"Phinees"}}}]