select public.upsert_bank_question($json${"id":"lei2-hard-012","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":25,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Em Números 25:7, quem se levantou do meio da congregação e tomou uma lança na mão?","bible_ref":"Números 25:7","verse_text":"E viu-o Fineias, filho de Eleazar, filho de Arão o sacerdote, e levantou-se do meio da congregação, e tomou uma lança em sua mão:"},"fr":{"prompt":"En Nombres 25:7, qui se leva du milieu de l’assemblée et prit une lance dans sa main ?","bible_ref":"Nombres 25:7","verse_text":"A cette vue, Phinées, fils d’Éléazar, fils du sacrificateur Aaron, se leva du milieu de l’assemblée, et prit une lance, dans sa main."},"en":{"prompt":"In Numbers 25:7, who rose up from among the congregation and took a javelin in his hand?","bible_ref":"Numbers 25:7","verse_text":"And when Phinehas, the son of Eleazar, the son of Aaron the priest, saw it, he rose up from among the congregation, and took a javelin in his hand;"},"es":{"prompt":"En Números 25:7, ¿quién se levantó de en medio de la congregación y tomó una lanza en su mano?","bible_ref":"Números 25:7","verse_text":"Y viólo Phinees, hijo de Eleazar, hijo de Aarón el sacerdote, y levantóse de en medio de la congregación, y tomó una lanza en su mano:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Fineias"},"fr":{"text":"Phinées"},"en":{"text":"Phinehas"},"es":{"text":"Phinees"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Itamar"},"fr":{"text":"Ithamar"},"en":{"text":"Ithamar"},"es":{"text":"Ithamar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-013","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":27,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Maalá, Noa, Hogla, Milca e Tirza eram filhas de quem?","bible_ref":"Números 27:1","verse_text":"E as filhas de Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, das famílias de Manassés, filho de José, os nomes das quais eram Maalá, e Noa, e Hogla, e Milca, e Tirza, chegaram;"},"fr":{"prompt":"Machla, Noa, Hogla, Milca et Thirtsa étaient les filles de qui ?","bible_ref":"Nombres 27:1","verse_text":"Les filles de Tselophchad, fils de Hépher, fils de Galaad, fils de Makir, fils de Manassé, des familles de Manassé, fils de Joseph, et dont les noms étaient Machla, Noa, Hogla, Milca et Thirtsa,"},"en":{"prompt":"Mahlah, Noah, Hoglah, Milcah and Tirzah were the daughters of whom?","bible_ref":"Numbers 27:1","verse_text":"Then came the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph: and these are the names of his daughters; Mahlah, Noah, and Hoglah, and Milcah, and Tirzah."},"es":{"prompt":"¿De quién eran hijas Maala, Noa, Hogla, Milca y Tirsa?","bible_ref":"Números 27:1","verse_text":"Y las hijas de Salphaad, hijo de Hepher, hijo de Galaad, hijo de Machîr, hijo de Manasés, de las familias de Manasés, hijo de José, los nombres de las cuales eran Maala, y Noa, y Hogla, y Milca, y Tirsa, llegaron;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Zelofeade"},"fr":{"text":"Tselophchad"},"en":{"text":"Zelophehad"},"es":{"text":"Salphaad"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Coré"},"fr":{"text":"Koré"},"en":{"text":"Korah"},"es":{"text":"Coré"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":4,"is_correct":false,"texts":{