select public.upsert_bank_question($json${"id":"lei2-hard-014","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":35,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Quantas das cidades dadas aos levitas seriam cidades de refúgio?","bible_ref":"Números 35:6","verse_text":"E das cidades que dareis aos levitas, seis cidades serão de refúgio, as quais dareis para que o homicida se acolha ali: e também destas dareis quarenta e duas cidades."},"fr":{"prompt":"Combien des villes données aux Lévites seraient des villes de refuge ?","bible_ref":"Nombres 35:6","verse_text":"Parmi les villes que vous donnerez aux Lévites, il y aura six villes de refuge où pourra s’enfuir le meurtrier, et quarante-deux autres villes."},"en":{"prompt":"How many of the cities given to the Levites were to be cities of refuge?","bible_ref":"Numbers 35:6","verse_text":"And among the cities which ye shall give unto the Levites there shall be six cities for refuge, which ye shall appoint for the manslayer, that he may flee thither: and to them ye shall add forty and two cities."},"es":{"prompt":"¿Cuántas de las ciudades dadas a los Levitas serían ciudades de acogimiento?","bible_ref":"Números 35:6","verse_text":"Y de las ciudades que daréis á los Levitas, seis ciudades serán de acogimiento, las cuales daréis para que el homicida se acoja allá: y además de éstas daréis cuarenta y dos ciudades."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"6"},"fr":{"text":"6"},"en":{"text":"6"},"es":{"text":"6"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"12"},"fr":{"text":"12"},"en":{"text":"12"},"es":{"text":"12"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"42"},"fr":{"text":"42"},"en":{"text":"42"},"es":{"text":"42"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-015","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":10,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Quantas trombetas de prata mandou Deus Moisés fazer?","bible_ref":"Números 10:2","verse_text":"Faze para ti duas trombetas de prata; de obra de martelo as farás, as quais te servirão para convocar a congregação, e para fazer mover o acampamento."},"fr":{"prompt":"Combien de trompettes d’argent Dieu ordonna-t-il à Moïse de faire ?","bible_ref":"Nombres 10:2","verse_text":"Fais-toi deux trompettes d’argent; tu les feras d’argent battu. Elles te serviront pour la convocation de l’assemblée et pour le départ des camps."},"en":{"prompt":"How many trumpets of silver did God tell Moses to make?","bible_ref":"Numbers 10:2","verse_text":"Make thee two trumpets of silver; of a whole piece shalt thou make them: that thou mayest use them for the calling of the assembly, and for the journeying of the camps."},"es":{"prompt":"¿Cuántas trompetas de plata mandó Dios a Moisés hacer?","bible_ref":"Números 10:2","verse_text":"Hazte dos trompetas de plata; de obra de martillo las harás, las cuales te servirán para convocar la congregación, y para hacer mover el campo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"2"},"fr":{"text":"2"},"en":{"text":"2"},"es":{"text":"2"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"4"},"fr":{"text":"4"},"en":{"text":"4"},"es":{"text":"4"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"12"},"fr":{"text":"12"},"en":{"text":"12"},"es":{"text":"12"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-016","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":27,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Em que monte ficariam seis tribos para abençoar o povo, depois de passar o Jordão?","bible_ref":"Deuteronómio 27:12","verse_text":"Estes estarão sobre o monte de Gerizim para abençoar ao povo, quando houverdes passado o Jordão: Simeão, e Levi, e Judá, e Issacar, e José e Benjamim."},"fr":{"prompt":"Sur quel mont six tribus se tiendraient-elles pour bénir le peuple, après le passage du Jourdain ?","bible_ref":"Deutéronome 27:12","verse_text":"Lorsque vous aurez passé le Jourdain, Siméon, Lévi, Juda, Issacar, Joseph et Benjamin, se tiendront sur le mont Garizim, pour bénir le peuple;"},"en":{"prompt":"On which mount would six tribes stand to bless the people, after crossing Jordan?","bible_ref":"Deuteronomy 27:12","verse_text":"These shall stand upon mount Gerizim to bless the people, when ye are come over Jordan; Simeon, and Levi, and Judah, and Issachar, and Joseph, and Benjamin:"},"es":{"prompt":"¿Sobre qué monte estarían seis tribus para bendecir al pueblo, pasado el Jordán?","bible_ref":"Deuteronomio 27:12","verse_text":"Estos estarán sobre el monte de Gerizim para bendecir al pueblo, cuando hubiereis pasado el Jordán: Simeón, y Leví, y Judá, é Issachâr, y José, y Benjamín."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gerizim"},"fr":{"text":"Garizim"},"en":{"text":"Gerizim"},"es":{"text":"Gerizim"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ebal"},"fr":{"text":"Ébal"},"en":{"text":"Ebal"},"es":{"text":"Ebal"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sinai"},"fr":{"text":"Sinaï"},"en":{"text":"Sinai"},"es":{"text":"Sinaí"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nebo"},"fr":{"text":"Nebo"},"en":{"text":"Nebo"},"es":{"text":"Nebo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-017","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":1,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Quantas jornadas havia desde Horebe até Cades-Barneia?","bible_ref":"Deuteronómio 1:2","verse_text":"Onze jornadas há desde Horebe, caminho do monte de Seir, até Cades-Barneia."},"fr":{"prompt":"Combien de journées y avait-il depuis Horeb jusqu’à Kadès-Barnéa ?","bible_ref":"Deutéronome 1:2","verse_text":"Il y a onze journées depuis Horeb, par le chemin de la montagne de Séir, jusqu’à Kadès-Barnéa."},"en":{"prompt":"How many days’ journey was it from Horeb unto Kadesh-barnea?","bible_ref":"Deuteronomy 1:2","verse_text":"(There are eleven days’ journey from Horeb by the way of mount Seir unto Kadesh-barnea.)"},"es":{"prompt":"¿Cuántas jornadas había desde Horeb hasta Cades-barnea?","bible_ref":"Deuteronomio 1:2","verse_text":"Once jornadas hay desde Horeb, camino del monte de Seir, hasta Cades-barnea."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"11"},"fr":{"text":"11"},"en":{"text":"11"},"es":{"text":"11"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"40"},"fr":{"text":"40"},"en":{"text":"40"},"es":{"text":"40"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-018","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":3,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"De que era feita a cama de Ogue, rei de Basã?","bible_ref":"Deuteronómio 3:11","verse_text":"Porque somente Ogue rei de Basã havia restado dos gigantes que restaram. Eis que sua cama, uma cama de ferro, não está em Rabá dos filhos de Amom?; o comprimento dela de nove côvados, e sua largura de quatro côvados, ao côvado de um homem."},"fr":{"prompt":"De quoi était fait le lit d’Og, roi de Basan ?","bible_ref":"Deutéronome 3:11","verse_text":"(Og, roi de Basan, était resté seul de la race des Rephaïm. Voici, son lit, un lit de fer, n’est-il pas à Rabbath, ville des enfants d’Ammon? Sa longueur est de neuf coudées, et sa largeur de quatre coudées, en coudées d’homme.)"},"en":{"prompt":"What was the bedstead of Og king of Bashan made of?","bible_ref":"Deuteronomy 3:11","verse_text":"For only Og king of Bashan remained of the remnant of giants; behold, his bedstead was a bedstead of iron; is it not in Rabbath of the children of Ammon? nine cubits was the length thereof, and four cubits the breadth of it, after the cubit of a man."},"es":{"prompt":"¿De qué era la cama de Og rey de Basán?","bible_ref":"Deuteronomio 3:11","verse_text":"Porque sólo Og rey de Basán había quedado de los gigantes que quedaron. He aquí su cama, una cama de hierro, ¿no está en Rabbath de los hijos de Ammón?; la longitud de ella de nueve codos, y su anchura de cuatro codos, al codo de un hombre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De ferro"},"fr":{"text":"De fer"},"en":{"text":"Of iron"},"es":{"text":"De hierro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De ouro"},"fr":{"text":"D’or"},"en":{"text":"Of gold"},"es":{"text":"De oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De cedro"},"fr":{"text":"De cèdre"},"en":{"text":"Of cedar"},"es":{"text":