select public.upsert_bank_question($json${"id":"lei2-hard-019","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":7,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Deuteronómio 7:7, como era Israel em comparação com os outros povos?","bible_ref":"Deuteronómio 7:7","verse_text":"Não por ser vós mais que todos os povos vos quis o SENHOR, e vos escolheu; porque vós éreis os menores de todos os povos:"},"fr":{"prompt":"D’après Deutéronome 7:7, qu’était Israël comparé aux autres peuples ?","bible_ref":"Deutéronome 7:7","verse_text":"Ce n’est point parce que vous surpassez en nombre tous les peuples, que l’Éternel s’est attaché à vous et qu’il vous a choisis, car vous êtes le moindre de tous les peuples."},"en":{"prompt":"According to Deuteronomy 7:7, what was Israel compared with other peoples?","bible_ref":"Deuteronomy 7:7","verse_text":"The LORD did not set his love upon you, nor choose you, because ye were more in number than any people; for ye were the fewest of all people:"},"es":{"prompt":"Según Deuteronomio 7:7, ¿qué era Israel comparado con los otros pueblos?","bible_ref":"Deuteronomio 7:7","verse_text":"No por ser vosotros más que todos los pueblos os ha querido Jehová, y os ha escogido; porque vosotros erais los más pocos de todos los pueblos:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O menor de todos os povos"},"fr":{"text":"Le moindre de tous les peuples"},"en":{"text":"The fewest of all people"},"es":{"text":"Los más pocos de todos los pueblos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O mais numeroso de todos"},"fr":{"text":"Le plus nombreux de tous"},"en":{"text":"The most numerous of all"},"es":{"text":"Los más numerosos de todos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O mais rico de todos"},"fr":{"text":"Le plus riche de tous"},"en":{"text":"The richest of all"},"es":{"text":"Los más ricos de todos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":