select public.upsert_bank_question($json${"id":"lei2-hard-020","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":22,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Ao edificar uma casa nova, o que devia fazer-se no terraço?","bible_ref":"Deuteronómio 22:8","verse_text":"Quando edificares casa nova, farás parapeito em teu terraço, para que não ponhas sangue em tua casa, se dele cair alguém."},"fr":{"prompt":"Quand on bâtissait une maison neuve, que fallait-il faire autour du toit ?","bible_ref":"Deutéronome 22:8","verse_text":"Si tu bâtis une maison neuve, tu feras une balustrade autour de ton toit, afin de ne pas mettre du sang sur ta maison, dans le cas où il en tomberait quelqu’un."},"en":{"prompt":"When building a new house, what was to be made for the roof?","bible_ref":"Deuteronomy 22:8","verse_text":"When thou buildest a new house, then thou shalt make a battlement for thy roof, that thou bring not blood upon thine house, if any man fall from thence."},"es":{"prompt":"Al edificar casa nueva, ¿qué había que hacer a la azotea?","bible_ref":"Deuteronomio 22:8","verse_text":"Cuando edificares casa nueva, harás pretil á tu terrado, porque no pongas sangre en tu casa, si de él cayere alguno."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um parapeito"},"fr":{"text":"Une balustrade"},"en":{"text":"A battlement"},"es":{"text":"Un pretil"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um altar"},"fr":{"text":"Un autel"},"en":{"text":"An altar"},"es":{"text":"Un altar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma torre"},"fr":{"text":"Une tour"},"en":{"text":"A tower"},"es":{"text":"Una torre"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma cisterna"},"fr":{"text":"Une citerne"},"en":{"text":"A cistern"},"es":{"text":"Una cisterna"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-021","type":"choice","level":"hard","testament":"ot","book":"DEU","chapter":19,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Segundo Deuteronómio 19:15, quantas testemunhas eram precisas para estabelecer um caso?","bible_ref":"Deuteronómio 19:15","verse_text":"Não valerá uma testemunha contra ninguém em qualquer delito, ou em qualquer pecado, em qualquer pecado que se cometer. No dito de duas testemunhas, ou no dito de três testemunhas consistirá o negócio."},"fr":{"prompt":"D’après Deutéronome 19:15, combien de témoins fallait-il pour établir un fait ?","bible_ref":"Deutéronome 19:15","verse_text":"Un seul témoin ne suffira pas contre un homme pour constater un crime ou un péché, quel qu’il soit; un fait ne pourra s’établir que sur la déposition de deux ou de trois témoins."},"en":{"prompt":"According to Deuteronomy 19:15, how many witnesses were needed to establish a matter?","bible_ref":"Deuteronomy 19:15","verse_text":"One witness shall not rise up against a man for any iniquity, or for any sin, in any sin that he sinneth: at the mouth of two witnesses, or at the mouth of three witnesses, shall the matter be established."},"es":{"prompt":"Según Deuteronomio 19:15, ¿cuántos testigos hacían falta para establecer un caso?","bible_ref":"Deuteronomio 19:15","verse_text":"No valdrá un testigo contra ninguno en cualquier delito, ó en cualquier pecado, en cualquier pecado que se cometiere. En el dicho de dos testigos, ó en el dicho de tres testigos consistirá el negocio."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Duas ou três"},"fr":{"text":"Deux ou trois"},"en":{"text":"Two or three"},"es":{"text":"Dos o tres"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma só"},"fr":{"text":"Un seul"},"en":{"text":"Only one"},"es":{"text":"Uno solo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"