select public.upsert_bank_question($json${"id":"lei2-hard-029","type":"verse","level":"hard","testament":"ot","book":"DEU","chapter":32,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Achou-o em terra de deserto, E em deserto horrível e ermo; Cercou-o, instruiu-o, Guardou-o como a _____ de seu olho.","bible_ref":"Deuteronómio 32:10","verse_text":"Achou-o em terra de deserto, E em deserto horrível e ermo; Cercou-o, instruiu-o, Guardou-o como a menina de seu olho."},"fr":{"prompt":"Il l’a trouvé dans une contrée déserte, Dans une solitude aux effroyables hurlements; Il l’a entouré, il en a pris soin, Il l’a gardé comme la _____ de son œil,","bible_ref":"Deutéronome 32:10","verse_text":"Il l’a trouvé dans une contrée déserte, Dans une solitude aux effroyables hurlements; Il l’a entouré, il en a pris soin, Il l’a gardé comme la prunelle de son œil,"},"en":{"prompt":"He found him in a desert land, and in the waste howling wilderness; he led him about, he instructed him, he kept him as the _____ of his eye.","bible_ref":"Deuteronomy 32:10","verse_text":"He found him in a desert land, and in the waste howling wilderness; he led him about, he instructed him, he kept him as the apple of his eye."},"es":{"prompt":"Hallólo en tierra de desierto, y en desierto horrible y yermo; trájolo alrededor, instruyólo, guardólo como la _____ de su ojo.","bible_ref":"Deuteronomio 32:10","verse_text":"Hallólo en tierra de desierto, y en desierto horrible y yermo; trájolo alrededor, instruyólo, guardólo como la niña de su ojo."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"lágrima"},"fr":{"text":"larme"},"en":{"text":"tear"},"es":{"text":"lágrima"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"luz"},"fr":{"text":"lumière"},"en":{"text":"light"},"es":{"text":"luz"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"menina"},"fr":{"text":"prunelle"},"en":{"text":"apple"},"es":{"text":"niña"}}},{"position":4,"is_correct":false,"texts":{"pt":{"te