select public.upsert_bank_question($json${"id":"lei2-hard-030","type":"verse","level":"hard","testament":"ot","book":"EXO","chapter":33,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"E falava o SENHOR a Moisés face a face, como fala qualquer um a seu _____. E voltava-se ao campo; mas o jovem Josué, seu criado, filho de Num, nunca se afastava do meio do tabernáculo.","bible_ref":"Êxodo 33:11","verse_text":"E falava o SENHOR a Moisés face a face, como fala qualquer um a seu companheiro. E voltava-se ao campo; mas o jovem Josué, seu criado, filho de Num, nunca se afastava do meio do tabernáculo."},"fr":{"prompt":"L’Éternel parlait avec Moïse face à face, comme un homme parle à son _____. Puis Moïse retournait au camp; mais son jeune serviteur, Josué, fils de Nun, ne sortait pas du milieu de la tente.","bible_ref":"Exode 33:11","verse_text":"L’Éternel parlait avec Moïse face à face, comme un homme parle à son ami. Puis Moïse retournait au camp; mais son jeune serviteur, Josué, fils de Nun, ne sortait pas du milieu de la tente."},"en":{"prompt":"And the LORD spake unto Moses face to face, as a man speaketh unto his _____. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle.","bible_ref":"Exodus 33:11","verse_text":"And the LORD spake unto Moses face to face, as a man speaketh unto his friend. And he turned again into the camp: but his servant Joshua, the son of Nun, a young man, departed not out of the tabernacle."},"es":{"prompt":"Y hablaba Jehová á Moisés cara á cara, como habla cualquiera á su _____. Y volvíase al campo; mas el joven Josué, su criado, hijo de Nun, nunca se apartaba de en medio del tabernáculo.","bible_ref":"Éxodo 33:11","verse_text":"Y hablaba Jehová á Moisés cara á cara, como habla cualquiera á su compañero. Y volvíase al campo; mas el joven Josué, su criado, hijo de Nun, nunca se apartaba de en medio del tabernáculo."}},"options":[{"position":1,"is_correct":true,"texts"