select public.upsert_bank_question($json${"id":"lei2-hard-031","type":"verse","level":"hard","testament":"ot","book":"LEV","chapter":26,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"E _____ entre vós, e eu serei vosso Deus, e vós sereis meu povo.","bible_ref":"Levítico 26:12","verse_text":"E andarei entre vós, e eu serei vosso Deus, e vós sereis meu povo."},"fr":{"prompt":"Je _____ au milieu de vous, je serai votre Dieu, et vous serez mon peuple.","bible_ref":"Lévitique 26:12","verse_text":"Je marcherai au milieu de vous, je serai votre Dieu, et vous serez mon peuple."},"en":{"prompt":"And I will _____ among you, and will be your God, and ye shall be my people.","bible_ref":"Leviticus 26:12","verse_text":"And I will walk among you, and will be your God, and ye shall be my people."},"es":{"prompt":"Y _____ entre vosotros, y yo seré vuestro Dios, y vosotros seréis mi pueblo.","bible_ref":"Levítico 26:12","verse_text":"Y andaré entre vosotros, y yo seré vuestro Dios, y vosotros seréis mi pueblo."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"reinarei"},"fr":{"text":"régnerai"},"en":{"text":"reign"},"es":{"text":"reinaré"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"dormirei"},"fr":{"text":"dormirai"},"en":{"text":"sleep"},"es":{"text":"dormiré"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"andarei"},"fr":{"text":"marcherai"},"en":{"text":"walk"},"es":{"text":"andaré"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"julgarei"},"fr":{"text":"jugerai"},"en":{"text":"judge"},"es":{"text":"juzgaré"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-032","type":"verse","level":"hard","testament":"ot","book":"NUM","chapter":24,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Verei, mas não agora: O olharei, mas não de perto: Sairá _____ de Jacó, E se levantará cetro de Israel, E ferirá os cantos de Moabe, E destruirá a todos os filhos de Sete.","bible_ref":"Números 24:17","verse_text":"Verei, mas não agora: O olharei, mas não de perto: Sairá estrela de Jacó, E se levantará cetro de Israel, E ferirá os cantos de Moabe, E destruirá a todos os filhos de Sete."},"fr":{"prompt":"Je le vois, mais non maintenant, Je le contemple, mais non de près. Un _____ sort de Jacob, Un sceptre s’élève d’Israël. Il perce les flancs de Moab, Et il abat tous les enfants de Seth.","bible_ref":"Nombres 24:17","verse_text":"Je le vois, mais non maintenant, Je le contemple, mais non de près. Un astre sort de Jacob, Un sceptre s’élève d’Israël. Il perce les flancs de Moab, Et il abat tous les enfants de Seth."},"en":{"prompt":"I shall see him, but not now: I shall behold him, but not nigh: there shall come a _____ out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth.","bible_ref":"Numbers 24:17","verse_text":"I shall see him, but not now: I shall behold him, but not nigh: there shall come a Star out of Jacob, and a Sceptre shall rise out of Israel, and shall smite the corners of Moab, and destroy all the children of Sheth."},"es":{"prompt":"Verélo, mas no ahora: lo miraré, mas no de cerca: saldrá _____ de Jacob, y levantaráse cetro de Israel, y herirá los cantones de Moab, y destruirá á todos los hijos de Seth.","bible_ref":"Números 24:17","verse_text":"Verélo, mas no ahora: lo miraré, mas no de cerca: saldrá ESTRELLA de Jacob, y levantaráse cetro de Israel, y herirá los cantones de Moab, y destruirá á todos los hijos de Seth."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"sol"},"fr":{"text":"soleil"},"en":{"text":"Sun"},"es":{"text":"sol"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"fogo"},"fr":{"text":"feu"},"en":{"text":"Fire"},"es":{"text":"fuego"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"estrela"},"fr":{"text":"astre"},"en":{"text":"Star"},"es":{"text":"estrella"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"espada"},"fr":{"text":"glaive"},"en":{"text":"Sword"},"es":{"text":"espada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-033","type":"verse","level":"hard","testament":"ot","book":"NUM","chapter":14,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"O SENHOR, tardio de ira e grande em _____, que perdoa a iniquidade e a rebelião, e deixa impune o culpado; que visita a maldade dos pais sobre os filhos até a terceira geração e até a quarta.","bible_ref":"Números 14:18","verse_text":"O SENHOR, tardio de ira e grande em misericórdia, que perdoa a iniquidade e a rebelião, e deixa impune o culpado; que visita a maldade dos pais sobre os filhos até a terceira geração e até a quarta."},"fr":{"prompt":"L’Éternel est lent à la colère et riche en _____, il pardonne l’iniquité et la rébellion; mais il ne tient point le coupable pour innocent, et il punit l’iniquité des pères sur les enfants jusqu’à la troisième et la quatrième génération.","bible_ref":"Nombres 14:18","verse_text":"L’Éternel est lent à la colère et riche en bonté, il pardonne l’iniquité et la rébellion; mais il ne tient point le coupable pour innocent, et il punit l’iniquité des pères sur les enfants jusqu’à la troisième et la quatrième génération."},"en":{"prompt":"The LORD is longsuffering, and of great _____, forgiving iniquity and transgression, and by no means clearing the guilty, visiting the iniquity of the fathers upon the children unto the third and fourth generation.","bible_ref":"Numbers 14:18","verse_text":"The LORD is longsuffering, and of great mercy, forgiving iniquity and transgression, and by no means clearing the guilty, visiting the iniquity of the fathers upon the children unto the third and fourth generation."},"es":{"prompt":"Jehová, tardo de ira y grande en _____, que perdona la iniquidad y la rebelión, y absolviendo no absolverá al culpado; que visita la maldad de los padres sobre los hijos hasta los terceros y hasta los cuartos.","bible_ref":"Números 14:18","verse_text":"Jehová, tardo de ira y grande en misericordia, que perdona la iniquidad y la rebelión, y absolviendo no absolverá al culpado; que visita la maldad de los padres sobre los hijos hasta los terceros y hasta los cuartos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"força"},"fr":{"text":"force"},"en":{"text":"strength"},"es":{"text":"fortaleza"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"sabedoria"},"fr":{"text":"sagesse"},"en":{"text":"wisdom"},"es":{"text":"sabiduría"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"glória"},"fr":{"text":"gloire"},"en":{"text":"glory"},"es":{"text":"gloria"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"misericórdia"},"fr":{"text":"bonté"},"en":{"text":"mercy"},"es":{"text":"misericordia"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"lei2-hard-034","type":"verse","level":"hard","testament":"ot","book":"DEU","chapter":29,"verse_start":29,"verse_end":29,"texts":{"pt":{"prompt":"As coisas _____ pertencem ao SENHOR nosso Deus: mas as reveladas são para nós e para nossos filhos para sempre, para que cumpramos todas as palavras desta lei.","bible_ref":"Deuteronómio 29:29","verse_text":"As coisas secretas pertencem ao SENHOR nosso Deus: mas as reveladas são para nós e para nossos filhos para sempre, para que cumpramos todas as palavras desta lei."},"fr":{"prompt":"Les choses _____ sont à l’Éternel, notre Dieu; les choses révélées sont à nous et à nos enfants, à perpétuité, afin que nous mettions en pratique toutes les paroles de cette loi.","bible_ref":"Deutéronome 29:29","verse_text":"Les choses cachées sont à l’Éternel, notre Dieu; les choses révélées sont à nous et à nos enfants, à perpétuité, afin que nous mettions en pratique toutes les paroles de cette loi."},"en":{"prompt":"The _____ things belong unto the LORD our God: but those things which are revealed belong unto us and to our children for ever, that we may do all the words of this law.","bible_ref":"Deuteronomy 29:29","verse_text":"The secret things belong unto the LORD our God: but those things which are revealed belong unto us and to our children for ever, that we may do all the words of this law."},"es":{"prompt":"Las cosas _____ pertenecen á Jehová nuestro Dios: mas las reveladas son para nosotros y para nuestros hijos por siempre, para que cumplamos todas las palabras de esta ley.","bible_ref":"Deuteronomio 29:29","verse_text":"Las cosas secretas pertenecen á Jehová nuestro Dios: mas las reveladas son para nosotros y para nuestros hijos por siempre, para que cumplamos todas las palabras de esta ley."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"grandes"},"fr":{"text":"grandes"},"en":{"text":"great"},"es":{"text":"grandes"}}},{"position":2,"is_correct":true,"texts":