select public.upsert_bank_question($json${"id":"lei2-hard-035","type":"verse","level":"hard","testament":"ot","book":"DEU","chapter":32,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Ele é a _____, sua obra é perfeita, pois todos os seus caminhos são justos. Deus fiel, e sem imoralidade; justo e correto ele é.","bible_ref":"Deuteronómio 32:4","verse_text":"Ele é a Rocha, sua obra é perfeita, pois todos os seus caminhos são justos. Deus fiel, e sem imoralidade; justo e correto ele é."},"fr":{"prompt":"Il est le _____; ses œuvres sont parfaites, Car toutes ses voies sont justes; C’est un Dieu fidèle et sans iniquité, Il est juste et droit.","bible_ref":"Deutéronome 32:4","verse_text":"Il est le rocher; ses œuvres sont parfaites, Car toutes ses voies sont justes; C’est un Dieu fidèle et sans iniquité, Il est juste et droit."},"en":{"prompt":"He is the _____, his work is perfect: for all his ways are judgment: a God of truth and without iniquity, just and right is he.","bible_ref":"Deuteronomy 32:4","verse_text":"He is the Rock, his work is perfect: for all his ways are judgment: a God of truth and without iniquity, just and right is he."},"es":{"prompt":"El es la _____, cuya obra es perfecta, porque todos sus caminos son rectitud: Dios de verdad, y ninguna iniquidad en él: es justo y recto.","bible_ref":"Deuteronomio 32:4","verse_text":"El es la Roca, cuya obra es perfecta, porque todos sus caminos son rectitud: Dios de verdad, y ninguna iniquidad en él: es justo y recto."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Coroa"},"fr":{"text":"diadème"},"en":{"text":"Crown"},"es":{"text":"Corona"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Torre"},"fr":{"text":"donjon"},"en":{"text":"Tower"},"es":{"text":"Torre"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"Rocha"},"fr":{"text":"rocher"},"en":{"text":"Rock"},"es":{"text":"Roca"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fortaleza"},"fr":{"text":"rempart"},"en":{"text":"Fortress"},"es":{"text":"Fortaleza"}}}]}$json$::jsonb);
